// --- FETCH PLAYER AVERAGES & RANKS ---
    async function fetchPlayerSeason() {
        try {
            const get = async (w) => {
                const r = await fetch(`${MFL_ORIGIN}/${year}/export?TYPE=playerScores&L=${lid}&W=${w}&YEAR=${year}&JSON=1`, { credentials: 'include', cache: 'no-store' });
                const d = await r.json();
                let l = d?.playerScores?.playerScore || [];
                if (!Array.isArray(l)) l = l ? [l] : [];
                return l;
            };
            const [ytd, avg] = await Promise.all([get('YTD'), get('AVG')]);
            const avgMap = {};
            avg.forEach(x => { if (x && x.id) avgMap[x.id] = parseFloat(x.score) || 0; });
            ytd.forEach(x => {
                if (!x || !x.id) return;
                const pts = parseFloat(x.score) || 0;
                const a = avgMap[x.id] || 0;
                playerSeason[x.id] = { pts, avg: a, gp: a ? Math.round(pts / a) : 0 };
            });
        } catch (e) { console.warn('Could not load season totals', e); }
    }
    async function fetchPlayerAverages() {
        try {
            const targetYear = parseInt(year) - 1; 
            const positions = ['QB', 'RB', 'WR', 'TE', 'PK', 'DE', 'DT', 'LB', 'CB', 'S'];
            
            const fetchPromises = positions.map(pos => {
                const isIDP = ['DE', 'DT', 'LB', 'CB', 'S'].includes(pos);
                const searchType = isIDP ? 'ADVANCED' : 'BASIC';
                const display = isIDP ? 'Defenders' : 'points';

                // Added &COUNT=300 and &SORT=AVG
                const url = `${MFL_ORIGIN}/${year}/top?L=${lid}&SEARCHTYPE=${searchType}&COUNT=300&YEAR=${targetYear}&START_WEEK=1&END_WEEK=18&CATEGORY=overall&POSITION=${pos}&DISPLAY=${display}&TEAM=*&SORT=AVG`;
                
                return fetch(url, { credentials: 'include', cache: 'no-store' })
                    .then(res => res.text())
                    .then(html => ({ pos, html })); // Pass the position string along with the HTML!
            });

            const results = await Promise.all(fetchPromises);

            results.forEach(({ pos, html }) => {
                const doc = new DOMParser().parseFromString(html, 'text/html');
                let posPlayers = []; // Temp array to hold players for this specific position

                doc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow').forEach(row => {
                    const pLink = row.querySelector('td.player a[class*="position_"]');
                    const avgTd = row.querySelector('td.avg') || row.querySelector('td.points.avg') || row.querySelectorAll('td')[3];
                    
                    if (pLink && avgTd) {
                        const pid = pLink.getAttribute('href').match(/\d+/g)?.pop();
                        if (pid) {
                            const avg = parseFloat(avgTd.textContent) || 0;
                            playerAverages[pid] = avg;
                            posPlayers.push({ pid: pid, avg: avg });
                        }
                    }
                });

                // Sort descending by average to guarantee accuracy
                posPlayers.sort((a, b) => b.avg - a.avg);

                // Assign the 1-through-300 Rank!
                posPlayers.forEach((p, index) => {
                    playerRanks[p.pid] = index + 1;
                });
            });
        } catch (err) {
            console.error("Failed to fetch player averages & ranks", err);
        }
    }
// --- FETCH POINTS ALLOWED (DEFENSIVE MATCHUPS & RANKS) ---
    async function fetchPointsAllowed() {
        try {
            const paRes = await fetch(`${MFL_ORIGIN}/${year}/options?L=${lid}&O=81`, { credentials: 'include', cache: 'no-store' });
            const paText = await paRes.text();
            const paDoc = new DOMParser().parseFromString(paText, 'text/html');

            paDoc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow').forEach(row => {
                const teamLink = row.querySelector('td.player a');
                if (!teamLink) return;

                const teamMatch = teamLink.getAttribute('href').match(/TEAM=([A-Z]+)/i);
                if (!teamMatch) return;
                const teamAbbr = teamMatch[1].toUpperCase();

                const cells = row.querySelectorAll('td.points');
                if (cells.length >= 20) {
                    pointsAllowedMap[teamAbbr] = {
                        "QB": cells[1].textContent.trim(), "RB": cells[3].textContent.trim(),
                        "WR": cells[5].textContent.trim(), "TE": cells[7].textContent.trim(),
                        "PK": cells[9].textContent.trim(), "DT": cells[11].textContent.trim(),
                        "DE": cells[13].textContent.trim(), "LB": cells[15].textContent.trim(),
                        "CB": cells[17].textContent.trim(), "S":  cells[19].textContent.trim()
                    };
                }
            });

            // --- CALCULATE THE 1-32 RANKS FOR EVERY POSITION ---
            const positions = ["QB", "RB", "WR", "TE", "PK", "DT", "DE", "LB", "CB", "S"];
            positions.forEach(pos => {
                let teamsList = [];
                for (let team in pointsAllowedMap) {
                    teamsList.push({ team: team, pts: parseFloat(pointsAllowedMap[team][pos]) || 0 });
                }
                
                // Sort from lowest points allowed (Rank 1 / Tough) to highest (Rank 32 / Easy)
                teamsList.sort((a, b) => a.pts - b.pts);
                
                pointsAllowedRankMap[pos] = {};
                teamsList.forEach((item, index) => {
                    pointsAllowedRankMap[pos][item.team] = index + 1;
                });
            });

        } catch (err) {
            console.error("Failed to fetch points allowed data", err);
        }
    }
// --- FETCH PENDING WAIVER CLAIMS (NOT YET PROCESSED) ---
// --- FETCH PENDING WAIVER CLAIMS (NOT YET PROCESSED) ---
async function fetchPendingWaivers() {
    window._pendingWaivers = {};
    window._pendingWaiversList = [];
    window._pendingWaiversRaw = [];
    try {
        const targetFid = (fid === '0000' ? myFid : fid).padStart(4, '0');
        const url = `${MFL_ORIGIN}/${year}/export?TYPE=pendingWaivers&L=${lid}&JSON=1&FRANCHISE_ID=${targetFid}`;
        const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
        const data = await res.json();

        // addsDrops can itself be a COMMA-separated list of "ADD_DROP" pairs — MFL treats these
        // as a ranked fallback chain within one round. orderIndex tracks each pick's position in
        // that chain so a cancel/reorder can resubmit the round in the right order.
        let claims = data?.pendingWaivers?.waiverRequest || [];
        if (!Array.isArray(claims)) claims = claims ? [claims] : [];

        for (const claim of claims) {
            const round = parseInt(claim.round, 10);
            const picks = (claim.addsDrops || '').split(',').map(s => s.trim()).filter(Boolean);

            for (let i = 0; i < picks.length; i++) {
                const pick = picks[i];
                window._pendingWaiversRaw.push({ round, addsDrops: pick, orderIndex: i });

                const [addPid, dropPidRaw] = pick.split('_');
                if (!addPid) continue;
                const dropPid = (dropPidRaw && dropPidRaw !== '0000') ? dropPidRaw : null;

                let addName = addPid, addShort = addPid, addPos = '', addTeam = 'NFL';
                try {
                    const pRes = await fetch(`${MFL_ORIGIN}/${year}/export?TYPE=players&L=${lid}&PLAYERS=${addPid}&JSON=1`, { credentials: 'include' });
                    const pData = await pRes.json();
                    const player = pData?.players?.player;
                    if (player?.name) {
                        addName = player.name.split(', ').reverse().join(' ');
                        const nameParts = addName.split(' ');
                        addShort = nameParts.length > 1 ? nameParts[0].charAt(0) + '. ' + nameParts.slice(1).join(' ') : addName;
                        addPos = player.position || '';
                        addTeam = player.team || 'NFL';
                    }
                } catch(e) { console.warn('Could not resolve waiver player', addPid, e); }

                let dropName = null;
                if (dropPid) {
                    try {
                        const dRes = await fetch(`${MFL_ORIGIN}/${year}/export?TYPE=players&L=${lid}&PLAYERS=${dropPid}&JSON=1`, { credentials: 'include' });
                        const dData = await dRes.json();
                        const dPlayer = dData?.players?.player;
                        if (dPlayer?.name) {
                            const fullDropName = dPlayer.name.split(', ').reverse().join(' ');
                            const dParts = fullDropName.split(' ');
                            dropName = dParts.length > 1 ? dParts[0].charAt(0) + '. ' + dParts.slice(1).join(' ') : fullDropName;
                        }
                    } catch(e) { console.warn('Could not resolve waiver drop player', dropPid, e); }
                }

                const entry = {
                    pid: addPid, name: addName, shortName: addShort, pos: addPos, team: addTeam,
                    dropName, priority: round || null, round, orderIndex: i,
                    dateText: claim.timestamp ? new Date(parseInt(claim.timestamp, 10) * 1000).toLocaleString([], { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' }) : ''
                };
                window._pendingWaivers[addPid] = entry;
                window._pendingWaiversList.push(entry);
            }
        }
    } catch (err) {
        console.error("Failed to fetch pending waiver claims", err);
    }
}

async function submitWaiverRoundUpdate(round, picksArray, targetFid) {
    const params = new URLSearchParams();
    params.set('TYPE', 'waiverRequest');
    params.set('L', lid);
    params.set('ROUND', round);
    params.set('PICKS', picksArray.join(','));
    params.set('REPLACE', '1');
    if (targetFid) params.set('FRANCHISE_ID', targetFid);
    const res = await fetch(`${MFL_ORIGIN}/${year}/import`, {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: params.toString()
    });
    return await res.text();
}

window.cancelWaiverClaim = async function(pid, btn) {
    if (!confirm('Cancel this waiver claim?')) return;
    const targetFid = (fid === '0000' ? myFid : fid).padStart(4, '0');
    const claim = (window._pendingWaiversRaw || []).find(c => c.addsDrops && c.addsDrops.split('_')[0] === String(pid));
    if (!claim) { alert('Could not find this claim — try refreshing.'); return; }

    const remaining = (window._pendingWaiversRaw || [])
        .filter(c => c.round === claim.round && c.addsDrops !== claim.addsDrops)
        .sort((a, b) => a.orderIndex - b.orderIndex)
        .map(c => c.addsDrops);

    if (btn) btn.text('Canceling...').prop('disabled', true);
    try {
        const txt = await submitWaiverRoundUpdate(claim.round, remaining, targetFid);
        if (txt.toLowerCase().includes('error')) {
            const m = txt.match(/<error[^>]*>(.*?)<\/error>/i);
            alert('MFL Error: ' + (m ? m[1] : 'Unknown'));
            if (btn) btn.text('Cancel Claim').prop('disabled', false);
            return;
        }
        await fetchPendingWaivers();
        loadPlayersData('free-agents');
    } catch (e) {
        console.error('Cancel waiver error', e);
        alert('Network error.');
        if (btn) btn.text('Cancel Claim').prop('disabled', false);
    }
};

window.changeWaiverRound = async function(pid, newRoundRaw, btn) {
    const newRound = parseInt(newRoundRaw, 10);
    if (!newRound || newRound < 1) { alert('Enter a valid round number.'); return; }
    const targetFid = (fid === '0000' ? myFid : fid).padStart(4, '0');
    const claim = (window._pendingWaiversRaw || []).find(c => c.addsDrops && c.addsDrops.split('_')[0] === String(pid));
    if (!claim) { alert('Could not find this claim — try refreshing.'); return; }
    if (newRound === claim.round) return;

    if (btn) btn.text('Saving...').prop('disabled', true);
    try {
        const oldRemaining = (window._pendingWaiversRaw || [])
            .filter(c => c.round === claim.round && c.addsDrops !== claim.addsDrops)
            .sort((a, b) => a.orderIndex - b.orderIndex)
            .map(c => c.addsDrops);
        let txt = await submitWaiverRoundUpdate(claim.round, oldRemaining, targetFid);
        if (txt.toLowerCase().includes('error')) {
            const m = txt.match(/<error[^>]*>(.*?)<\/error>/i);
            alert('MFL Error removing from old round: ' + (m ? m[1] : 'Unknown'));
            if (btn) btn.text('Save').prop('disabled', false);
            return;
        }

        const newRoundExisting = (window._pendingWaiversRaw || [])
            .filter(c => c.round === newRound)
            .sort((a, b) => a.orderIndex - b.orderIndex)
            .map(c => c.addsDrops);
        txt = await submitWaiverRoundUpdate(newRound, [...newRoundExisting, claim.addsDrops], targetFid);
        if (txt.toLowerCase().includes('error')) {
            const m = txt.match(/<error[^>]*>(.*?)<\/error>/i);
            alert('MFL Error adding to new round: ' + (m ? m[1] : 'Unknown'));
            if (btn) btn.text('Save').prop('disabled', false);
            return;
        }

        await fetchPendingWaivers();
        loadPlayersData('free-agents');
    } catch (e) {
        console.error('Change waiver round error', e);
        alert('Network error.');
        if (btn) btn.text('Save').prop('disabled', false);
    }
};

window.reorderWaiverClaim = async function(pid, direction, btn) {
    const targetFid = (fid === '0000' ? myFid : fid).padStart(4, '0');
    const claim = (window._pendingWaiversRaw || []).find(c => c.addsDrops && c.addsDrops.split('_')[0] === String(pid));
    if (!claim) { alert('Could not find this claim — try refreshing.'); return; }

    const roundPicks = (window._pendingWaiversRaw || [])
        .filter(c => c.round === claim.round)
        .sort((a, b) => a.orderIndex - b.orderIndex)
        .map(c => c.addsDrops);

    const idx = roundPicks.indexOf(claim.addsDrops);
    const swapIdx = idx + direction;
    if (idx === -1 || swapIdx < 0 || swapIdx >= roundPicks.length) return;

    [roundPicks[idx], roundPicks[swapIdx]] = [roundPicks[swapIdx], roundPicks[idx]];

    if (btn) btn.prop('disabled', true).css('opacity', '0.4');
    try {
        const txt = await submitWaiverRoundUpdate(claim.round, roundPicks, targetFid);
        if (txt.toLowerCase().includes('error')) {
            const m = txt.match(/<error[^>]*>(.*?)<\/error>/i);
            alert('MFL Error: ' + (m ? m[1] : 'Unknown'));
        }
        await fetchPendingWaivers();
        loadPlayersData('free-agents');
    } catch (e) {
        console.error('Reorder waiver error', e);
        alert('Network error.');
    }
};
// Resubmits a round's entire PICKS list. REPLACE=1 means "this list IS the round now" —
// which is what makes both cancel (list minus one) and move (list plus/minus one) work.
async function submitWaiverRoundUpdate(round, picksArray, targetFid) {
    const params = new URLSearchParams();
    params.set('TYPE', 'waiverRequest');
    params.set('L', lid);
    params.set('ROUND', round);
    params.set('PICKS', picksArray.join(','));
    params.set('REPLACE', '1');
    if (targetFid) params.set('FRANCHISE_ID', targetFid);
    const res = await fetch(`${MFL_ORIGIN}/${year}/import`, {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: params.toString()
    });
    return await res.text();
}

