                if (['DE','DT'].includes(p)) p = 'DL'; if (['CB','S'].includes(p)) p = 'DB'; 
                
                const pid = $(this).data('pid').toString();
                if (irPids.has(pid)) totalIR++;
                else if (taxiPids.has(pid)) totalTaxi++;
                else { rCounts[p] = (rCounts[p] || 0) + 1; totalPlayers++; }
