// ROSTER FULL: pop up your roster so you can check which player(s) to drop to make room for the add.
async function openDropToAddModal(addPid) {
        const targetFid = (fid === '0000' ? myFid : fid).padStart(4, '0');
        const salaryCapAmt = window.leagueSalaryCap || LLD.salaryCap;

        // Default contract every added free agent receives (salary in $m). 0% guaranteed = no cap hit.
        const NEW_CONTRACT = { sal: 1.0, yrs: 1, guar: 0 };
        const newHit = parseFloat((NEW_CONTRACT.sal * (NEW_CONTRACT.guar / 100) * NEW_CONTRACT.yrs).toFixed(1));

        // Info on the player being added, read from the row you tapped Add on
        const $addRow = $(`.player-row[data-pid="${addPid}"]`).first();
        const addName = $addRow.attr('data-pname') || 'this player';
        const addPos = ($addRow.attr('data-ppos') || '').toUpperCase();
        const addTeam = $addRow.attr('data-pteam') || '';

        const closeJs = "$('#drop-add-modal').remove(); $('body').css('overflow','');";
        $('#drop-add-modal').remove();
        $('body').append(`<div id="drop-add-modal" class="player-modal-backdrop" style="z-index:99999; display:flex;"><div class="player-modal-box" style="padding:30px; max-width:420px; text-align:center; color:var(--text-dim); font-size:calc(11px * var(--ts,1)); font-weight:800; text-transform:uppercase;">Loading roster...</div></div>`).css('overflow', 'hidden');

        let players = [];
        try {
            const res = await fetch(`${MFL_ORIGIN}/${year}/options?L=${lid}&O=07&F=${targetFid}&rnd=${Date.now()}`, { credentials: 'include', cache: 'no-store' });
            const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
            doc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow').forEach(row => {
                const pLink = row.querySelector('td.player a[class*="position_"]');
                if (!pLink) return;
                const pid = pLink.getAttribute('href').match(/\d+/g)?.pop();
                if (!pid) return;
                const { name, pos, team } = parseMFLName(pLink.textContent);
                const salaryText = row.querySelector('td.salary')?.textContent.trim() || '';
                const salNum = parseFloat(salaryText.replace(/[^0-9.]/g, '')) || 0;
                const yrsNum = parseInt(row.querySelector('td.contractyear')?.textContent) || 0;
                const guarText = row.querySelector('td.contractinfo')?.textContent.trim() || '';
                const gPct = (parseFloat(guarText.replace(/[^0-9.]/g, '')) || 0) / 100;
                players.push({ pid, name, pos: pos || '', team: team || '', salaryText, salNum, yrsNum, guarText, hit: parseFloat((salNum * gPct * yrsNum).toFixed(1)) });
            });
        } catch (e) { console.warn('Drop modal roster fetch failed', e); }

        if (!players.length) {
            $('#drop-add-modal .player-modal-box').html(`<div style="color:#ef4444;">Couldn't load your roster.</div><button onclick="${closeJs}" style="margin-top:14px; padding:10px 16px; background:rgba(255,255,255,0.05); color:var(--text-dim); border:1px solid var(--card-border); border-radius:8px; font-size:calc(12px * var(--ts,1)); font-weight:900; cursor:pointer;">Close</button>`);
            return;
        }

        // The roster limit only counts ACTIVE players (IR and Taxi don't count), same as your ROSTER counter.
        // irPids/taxiPids are for the team on screen; if you're acting for a different team, look them up.
        const viewedIsTarget = String(fid).padStart(4, '0') === targetFid;
        let irSet = irPids, taxiSet = taxiPids;
        if (!viewedIsTarget) {
            irSet = new Set(); taxiSet = new Set();
            const grab = async (O, key, set) => {
                const r = await fetch(`${MFL_ORIGIN}/${year}/options?L=${lid}&O=${O}&F=${targetFid}&rnd=${Date.now()}`, { credentials: 'include', cache: 'no-store' });
                const d = new DOMParser().parseFromString(await r.text(), 'text/html');
                d.querySelectorAll('table.report').forEach(t => {
                    if (!(t.querySelector('th')?.textContent.toLowerCase() || '').includes(key)) return;
                    t.querySelectorAll('tr.oddtablerow, tr.eventablerow').forEach(rw => {
                        const a = rw.querySelector('td.player a, td a[class*="position_"]');
                        const pid = a?.getAttribute('href').match(/\d+/g)?.pop();
                        if (pid) set.add(pid);
                    });
                });
            };
            try { await Promise.all([grab(18, 'activate from', irSet), grab(98, 'promote', taxiSet)]); }
            catch (e) { console.warn('IR/Taxi lookup failed', e); }
        }
        const activePlayers = players.filter(p => !irSet.has(p.pid) && !taxiSet.has(p.pid));
        const need = Math.max(1, activePlayers.length + 1 - LINEUP_RULES.rosterLimit);
        // Salary counts everyone on the roster (IR and Taxi salaries still count against the cap)
        const totalSal = parseFloat(players.reduce((s, p) => s + p.salNum, 0).toFixed(1));
        // Only active players are listed: dropping an IR/Taxi player wouldn't open an active roster spot
        activePlayers.sort((a, b) => (a.hit - b.hit) || (a.salNum - b.salNum));

        const rowsHtml = activePlayers.map(p => {
            const tag = '';
            return `
            <label style="display:flex; align-items:center; gap:10px; padding:8px; background:rgba(0,0,0,0.2); border-radius:8px; margin-bottom:6px; border-left:3px solid #ef4444; cursor:pointer;">
                <input type="checkbox" class="drop-cb" data-pid="${p.pid}" data-sal="${p.salNum}" data-hit="${p.hit}" style="width:16px; height:16px; flex-shrink:0;">
                <div style="width:36px; height:36px; border-radius:50%; overflow:hidden; background:var(--card-bg); flex-shrink:0;">
                    <img src="https://www.mflscripts.com/playerImages_80x107/mfl_${p.pid}.png" onerror="this.style.display='none'" style="width:100%; height:100%; object-fit:cover;">
                </div>
                <div style="flex:1; min-width:0;">
                    <div style="display:flex; align-items:center; gap:6px;">
                        <span style="font-size:calc(12px * var(--ts,1)); font-weight:900; color:#fff; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${p.name}</span>
                        <span class="pos-text-${p.pos.toLowerCase()}" style="font-size:calc(8px * var(--ts,1)); font-weight:900;">${p.pos}</span>
                        ${tag ? `<span style="font-size:calc(8px * var(--ts,1)); font-weight:900; color:#f59e0b; border:1px solid rgba(245,158,11,0.4); border-radius:4px; padding:0 4px;">${tag}</span>` : ''}
                    </div>
                    <div style="font-size:calc(9px * var(--ts,1)); color:var(--text-dim); font-weight:700; margin-top:2px;">${p.team} · ${p.salaryText} · ${p.yrsNum}yr · ${p.guarText}</div>
                </div>
                <div style="text-align:right; flex-shrink:0;">
                    <div style="font-size:calc(12px * var(--ts,1)); font-weight:900; color:#ef4444;">$${p.hit.toFixed(1)}m</div>
                    <div style="font-size:calc(7px * var(--ts,1)); color:var(--text-dim); font-weight:800; text-transform:uppercase;">cap hit</div>
                </div>
            </label>`;
        }).join('');

        const row = (label, valueHtml, extra = '') => `<span style="color:var(--text-dim); ${extra}">${label}</span><span style="text-align:right; ${extra}">${valueHtml}</span>`;

        const modalHtml = `
        <div id="drop-add-modal" class="player-modal-backdrop" style="z-index:99999; display:flex;">
            <div class="player-modal-box" style="padding:0; overflow:hidden; max-width:420px;">
                <button class="player-modal-close" onclick="${closeJs}">✕</button>
                <div style="padding:16px 20px; border-bottom:1px solid var(--card-border); background:rgba(239,68,68,0.08);">
                    <div style="font-size:calc(14px * var(--ts,1)); font-weight:900; color:#fff; text-transform:uppercase; letter-spacing:1px;">Roster Full</div>
                    <div style="font-size:calc(10px * var(--ts,1)); color:var(--text-dim); margin-top:3px;">Select ${need} player${need > 1 ? 's' : ''} to drop to make room</div>
                </div>
                <div style="padding:12px 16px 0;">
                    <div style="display:flex; align-items:center; gap:10px; padding:8px; background:rgba(34,197,94,0.08); border-radius:8px; border-left:3px solid #22c55e;">
                        <div style="width:36px; height:36px; border-radius:50%; overflow:hidden; background:var(--card-bg); flex-shrink:0;">
                            <img src="https://www.mflscripts.com/playerImages_80x107/mfl_${addPid}.png" onerror="this.style.display='none'" style="width:100%; height:100%; object-fit:cover;">
                        </div>
                        <div style="flex:1; min-width:0;">
                            <div style="font-size:calc(8px * var(--ts,1)); font-weight:900; color:#22c55e; text-transform:uppercase; letter-spacing:1px;">Adding</div>
                            <div style="display:flex; align-items:center; gap:6px;">
                                <span style="font-size:calc(13px * var(--ts,1)); font-weight:900; color:#fff;">${addName}</span>
                                <span class="pos-text-${addPos.toLowerCase()}" style="font-size:calc(8px * var(--ts,1)); font-weight:900;">${addPos}</span>
                                <span style="font-size:calc(9px * var(--ts,1)); color:var(--text-dim); font-weight:700;">${addTeam}</span>
                            </div>
                            <div style="font-size:calc(9px * var(--ts,1)); color:var(--text-dim); font-weight:700; margin-top:2px;">$${NEW_CONTRACT.sal.toFixed(1)}m · ${NEW_CONTRACT.yrs}yr · ${NEW_CONTRACT.guar}% guar · <span style="color:#ef4444;">$${newHit.toFixed(1)}m hit</span></div>
                        </div>
                    </div>
                    <div style="font-size:calc(9px * var(--ts,1)); font-weight:900; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin:10px 2px 8px;">Your Active Roster (${activePlayers.length}) · IR &amp; Taxi not listed</div>
                </div>
                <div style="padding:0 16px; max-height:36vh; overflow-y:auto;">${rowsHtml}</div>
                <div style="padding:10px 16px; border-top:1px solid var(--card-border); background:rgba(0,0,0,0.2);">
                    <div id="drop-sel-count" style="font-size:calc(9px * var(--ts,1)); font-weight:900; color:var(--text-dim); text-transform:uppercase; margin-bottom:6px;">0 selected · ${need} needed</div>
                    <div style="display:grid; grid-template-columns:1fr auto; gap:3px 12px; font-size:calc(10px * var(--ts,1)); font-weight:800; color:#fff;">
                        ${row('Current salary', `$${totalSal.toFixed(1)}m`)}
                        ${row('− Salary dropped', '<span id="drop-sel-sal">$0.0m</span>')}
                        ${row('+ Cap hit from drops', '<span id="drop-sel-hit" style="color:#ef4444;">$0.0m</span>')}
                        ${row(`+ New contract ($${NEW_CONTRACT.sal.toFixed(1)}m, ${NEW_CONTRACT.guar}% guar)`, `$${NEW_CONTRACT.sal.toFixed(1)}m`)}
                        ${row('Net salary change', '<span id="drop-net"></span>', 'font-weight:900;')}
                        <span style="border-top:1px solid var(--card-border); padding-top:4px; font-size:calc(11px * var(--ts,1)); font-weight:900;">Salary after</span>
                        <span id="drop-after" style="border-top:1px solid var(--card-border); padding-top:4px; text-align:right; font-size:calc(11px * var(--ts,1)); font-weight:900;"></span>
                        ${row('Cap remaining', '<span id="drop-remaining"></span>')}
                    </div>
                </div>
                <div style="padding:12px 16px; border-top:1px solid var(--card-border); display:flex; gap:8px;">
                    <button id="drop-add-confirm" disabled style="flex:1; padding:10px; background:#00ceb8; color:var(--card-bg); border:none; border-radius:8px; font-size:calc(12px * var(--ts,1)); font-weight:900; text-transform:uppercase; cursor:not-allowed; opacity:0.4;">Select players to drop</button>
                    <button onclick="${closeJs}" style="padding:10px 16px; background:rgba(255,255,255,0.05); color:var(--text-dim); border:1px solid var(--card-border); border-radius:8px; font-size:calc(12px * var(--ts,1)); font-weight:900; cursor:pointer;">Cancel</button>
                </div>
            </div>
        </div>`;

        window._dropAdd = { addPid, need };
        $('#drop-add-modal').replaceWith(modalHtml);

        // Recompute everything whenever a checkbox changes
        const recalc = () => {
            let n = 0, sal = 0, hit = 0;
            $('.drop-cb:checked').each(function() { n++; sal += parseFloat($(this).data('sal')) || 0; hit += parseFloat($(this).data('hit')) || 0; });
            const net = parseFloat((NEW_CONTRACT.sal + newHit + hit - sal).toFixed(1));
            const after = parseFloat((totalSal + net).toFixed(1));
            const remaining = parseFloat((salaryCapAmt - after).toFixed(1));
            const pct = (after / salaryCapAmt) * 100;
            const color = after > salaryCapAmt ? '#ef4444' : pct > 90 ? '#f59e0b' : '#22c55e';
            const ok = n >= need;
            $('#drop-sel-count').text(`${n} selected · ${need} needed`);
            $('#drop-sel-sal').text(`$${sal.toFixed(1)}m`);
            $('#drop-sel-hit').text(`$${hit.toFixed(1)}m`);
            $('#drop-net').text(`${net >= 0 ? '+' : '-'}$${Math.abs(net).toFixed(1)}m`).css('color', net > 0 ? '#ef4444' : net < 0 ? '#22c55e' : '#fff');
            $('#drop-after').text(`$${after.toFixed(1)}m / $${salaryCapAmt}m`).css('color', color);
            $('#drop-remaining').text(remaining < 0 ? `-$${Math.abs(remaining).toFixed(1)}m (over cap)` : `$${remaining.toFixed(1)}m`).css('color', color);
            $('#drop-add-confirm').prop('disabled', !ok).css({ opacity: ok ? 1 : 0.4, cursor: ok ? 'pointer' : 'not-allowed' }).text(ok ? `Drop ${n} & Add` : 'Select players to drop');
        };
        $(document).off('change.dropadd', '.drop-cb').on('change.dropadd', '.drop-cb', recalc);
        $(document).off('click.dropadd', '#drop-add-confirm').on('click.dropadd', '#drop-add-confirm', function() {
            const drops = $('.drop-cb:checked').map(function() { return String($(this).data('pid')); }).get();
            if (!drops.length || !window._dropAdd) return;
            const addId = window._dropAdd.addPid;
            $('#drop-add-modal').remove();
            $('body').css('overflow', '');
            executeTransaction('add-drop', addId, drops.join(','), $('<button></button>'));
        });
        recalc();
    }
async function executeTransaction(type, sourcePid, targetPid, btn) {
        // Handle Roster Full logic for simple adds
        if (type === 'add' && window.currentRosterSize >= LINEUP_RULES.rosterLimit) {
openDropToAddModal(sourcePid);
            return;
        }

        btn.text('Processing...').css({'opacity': '0.5', 'pointer-events': 'none'});

        const targetFid = (fid === '0000' ? myFid : fid).padStart(4, '0');
        let res;

        try {
            if (['activate', 'deactivate', 'swap-ir', 'promote', 'demote', 'swap-ts'].includes(type)) {
                // IR/Taxi moves now use the SAME request format as the header's IR/Taxi buttons
                // (txAction) — that's the format MFL actually accepts. The old ADD/DROP-style
                // params previously sent here never worked for these three action types.
                const isIrType = ['activate', 'deactivate', 'swap-ir'].includes(type);
                const endpoint = isIrType ? 'ir' : 'taxi_squad';
                const apiData = new URLSearchParams();
                apiData.append('LEAGUE_ID', lid);
                apiData.append('FRANCHISE_ID', targetFid);
                if (type === 'activate') apiData.append('activate' + targetFid, sourcePid);
                if (type === 'deactivate') apiData.append('deactivate' + targetFid, sourcePid);
                if (type === 'swap-ir') { apiData.append('deactivate' + targetFid, sourcePid); apiData.append('activate' + targetFid, targetPid); }
                if (type === 'promote') apiData.append('promote' + targetFid, sourcePid);
                if (type === 'demote') apiData.append('demote' + targetFid, sourcePid);
                if (type === 'swap-ts') { apiData.append('demote' + targetFid, sourcePid); apiData.append('promote' + targetFid, targetPid); }
                res = await fetch(`${MFL_ORIGIN}/${year}/${endpoint}`, {
                    method: 'POST', body: apiData, credentials: 'include', cache: 'no-store'
                });
            } else {
                const apiData = new URLSearchParams();
                apiData.append('L', lid);
                apiData.append('TYPE', 'fcfsWaiver');
                if (type === 'add') apiData.append('ADD', sourcePid);
                else if (type === 'add-drop') { apiData.append('ADD', sourcePid); apiData.append('DROP', targetPid); }
                if (fid !== myFid) apiData.append('FRANCHISE_ID', targetFid);
                res = await fetch(`${MFL_ORIGIN}/${year}/import`, {
                    method: 'POST', body: apiData, credentials: 'include'
                });
            }
            let responseText = await res.text();
let wasWaiverClaim = false;
            if (type === 'add' && /maximum roster size/i.test(responseText)) {
                btn.text('Add').css({'opacity': '1', 'pointer-events': 'auto'});
                openDropToAddModal(sourcePid);
                return;
            }
            if (responseText.toLowerCase().includes('error') && (type === 'add' || type === 'add-drop')) {
                const waiverData = new URLSearchParams();
                waiverData.append('L', lid);
                waiverData.append('TYPE', 'waiverRequest');
                waiverData.append('ROUND', '1');
                waiverData.append('PICKS', `${sourcePid}_${type === 'add-drop' ? String(targetPid).split(',')[0] : '0000'}`);
                if (fid !== myFid) waiverData.append('FRANCHISE_ID', fid);

                const waiverRes = await fetch(`${MFL_ORIGIN}/${year}/import`, {
                    method: 'POST', body: waiverData, credentials: 'include'
                });
                responseText = await waiverRes.text();
                wasWaiverClaim = true;
            }

            const __isMove = ['activate', 'deactivate', 'swap-ir', 'promote', 'demote', 'swap-ts'].includes(type);
            // IR/Taxi responses are full HTML pages that can mention "error" in harmless places; only a real <error> tag counts
            const __rejected = __isMove ? /<error[^>]*>/i.test(responseText) : responseText.toLowerCase().includes('error');
            if (__rejected) {
                console.warn('[tx] MFL response for', type, responseText.slice(0, 600));
                alert("MFL Rejected: " + lldMflError(responseText));
                btn.text('Error').css({'opacity': '1', 'pointer-events': 'auto', 'background': '#ef4444'});
} else {
    alert(wasWaiverClaim ? "Player is locked — submitted as a waiver claim (Round 1) instead." : "Transaction successful!");
    hideMenu();
    try {
        if (wasWaiverClaim) { btn.text('Claim sent').css({'opacity': '.6', 'pointer-events': 'none'}); }
        else { btn.text('Added').css({'opacity': '.6', 'pointer-events': 'none'}); }
        window._playerRowsCache = {};
        const __fa = $('#players-content-container:visible');
        if (__fa.length) {
            const __sb = $('#subtabs-players .sub-tab-btn.active');
            const __sid = __sb.length ? __sb.text().trim().toLowerCase().replace(' ', '-') : 'free-agents';
            loadPlayersData(__sid);
        }
    } catch (_) {}
    await fetchMasterStatus(); 
window._teamDataDirty = true;
    await loadTeamData();
}
        } catch (e) { 
            console.error("Transaction Error", e); 
            btn.text('Error').css({'opacity': '1', 'pointer-events': 'auto', 'background': '#ef4444'}); 
        }
    }
$(document).off('click', '#year-selector-pill').on('click', '#year-selector-pill', function(e) {
    e.stopPropagation();
    e.preventDefault();
    window._yearSelectorOpen = !window._yearSelectorOpen;
    window._teamDataDirty = true;
    loadTeamData();
});

$(document).off('click', '.year-selector-item').on('click', '.year-selector-item', function(e) {
    e.stopPropagation();
    selectedYear = parseInt($(this).data('year'));
    window._yearSelectorOpen = false;
    window._teamDataDirty = true;
    loadTeamData();
});

let isConfirming = false; 
    window.confirmAndSubmit = function() {
        if (isConfirming) return; isConfirming = true;        
        const { added, removed } = getLineupChanges();
        let message = "Are you sure you want to save these changes?\n\n";
        if (added.length > 0) message += `✅ Starting ${added.length} player(s)\n`;
        if (removed.length > 0) message += `🪑 Benching ${removed.length} player(s)\n`;

        if (confirm(message)) {
            const isCommish = true; // 🔑 YOUR MASTER KEY
            const isOverride = (fid !== myFid && isCommish && window.commishDoc);
            
            let submitTargetURL;
            let payloadData = "";

            if (isOverride) {
                submitTargetURL = `${MFL_ORIGIN}/${year}/options`;
                let params = new URLSearchParams();
                
                // CRITICAL FIX 1: Grab ALL hidden inputs from the Commish page (This includes 'W' for Week!)
                window.commishDoc.querySelectorAll('input[type="hidden"]').forEach(inp => {
                    params.append(inp.name, inp.value);
                });
                
                // Ensure the core routing parameters are explicitly set
                params.set('L', lid);
                params.set('O', '02');
                params.set('FRANCHISE_ID', fid);
                params.set('F', '0000'); // Force God-Mode
                
                let validStarters = Array.from(currentDoc.querySelectorAll('input[type="checkbox"]:checked'))
                    .map(cb => cb.value)
                    .filter(val => !irPids.has(val) && !taxiPids.has(val));
                
                // CRITICAL FIX 2: Map our checked players back into MFL's exact dropdown names
                let allDropdowns = Array.from(window.commishDoc.querySelectorAll('select')).filter(s => s.name.startsWith('starter'));
                
                allDropdowns.forEach((d, index) => {
                    let pidToStart = validStarters[index] || ""; // Leaves it blank if we run out of starters
                    params.append(d.name, pidToStart);
                });
                
                params.append('submit', 'Save Lineup'); 
                payloadData = params.toString();
                
            } else {
                submitTargetURL = `${MFL_ORIGIN}/${year}/lineup?L=${lid}&F=${fid}`;
                const normalForm = currentDoc.querySelector('form[name="lineupForm"]') || currentDoc.querySelector('form');
                payloadData = $(normalForm).serialize() + '&submit=Submit%20Lineup'; 
            }

            $.ajax({
                type: "POST", 
                url: submitTargetURL, 
                data: payloadData, 
                success: function() {
                    alert("Lineup saved successfully!");
                    originalStarterIds.clear();
                    currentDoc.querySelectorAll('input[type="checkbox"]:checked').forEach(cb => { originalStarterIds.add(cb.value); });
                    renderActiveTab(); 
                },
                error: function() { alert("Error saving lineup. Please try again."); },
                complete: function() { setTimeout(() => { isConfirming = false; }, 300); }
            });
        } else { setTimeout(() => { isConfirming = false; }, 300); }
    };


    $(document).on('click touchend', '#lineup-submit-float', function(e) { e.preventDefault(); window.confirmAndSubmit(); });
    $(document).on('click touchend', '.preview-action-btn', function(e) { if (e.type === 'touchend' && touchMoved) return; const checkbox = currentDoc.querySelector(`input[value="${$(this).data('action-pid')}"]`); if (checkbox) { checkbox.checked = !checkbox.checked; hideMenu(); setTimeout(renderActiveTab, 50); } });
        $(document).on('click touchend', '.swap-item:not(.active-player-preview)', function(e) {
        if (e.type === 'touchend' && touchMoved) return;
        if ($(e.target).closest('.proj-popup-trigger, .pa-breakdown-trigger').length) return;
        if (e.type === 'touchend') e.preventDefault();
        const tPid = $(this).data('pid');
        const tCb = currentDoc.querySelector(`input[value="${tPid}"]`);
        const sPid = (activePlayerRow && activePlayerRow.data('pid')) || window._modalCurrentPid;
        const sCb = sPid ? currentDoc.querySelector(`input[value="${sPid}"]`) : null;
        if (tCb) { tCb.checked = !tCb.checked; if (sCb) sCb.checked = !sCb.checked; }
        hideMenu();
        $('#smart-player-modal').fadeOut(200);
        $('body').css('overflow', '');
        setTimeout(renderActiveTab, 50);
    });
