if (tradeBlockGiveUp.length === 0 || window._tbSeededFor !== fid) {
            window._tbSeededFor = fid;
            tradeBlockGiveUp = [];
            try {
                const tbRes = await fetch(`${MFL_ORIGIN}/${year}/export?TYPE=tradeBait&L=${lid}&JSON=1`, { credentials: 'include', cache: 'no-store' });
                const tbData = await tbRes.json();
                if (tbData?.tradeBaits?.tradeBait) {
                    let baits = tbData.tradeBaits.tradeBait;
                    if (!Array.isArray(baits)) baits = [baits];
const myBait = baits.find(b => String(b.franchise_id || b.franchise).padStart(4, '0') === String(fid).padStart(4, '0'));
                    // Store ALL teams' trade blocks
                    if (!Array.isArray(baits)) baits = [baits];
                    baits.forEach(bait => {
                        const bFid = bait.franchise_id || bait.franchise;
                        (bait.willGiveUp || '').split(',').filter(Boolean).forEach(id => tradeBlockPids.add(String(id)));
                    });                    if (myBait) {
                        tradeBlockGiveUp = (myBait.willGiveUp || '').split(',').filter(Boolean);
                        tradeBlockGiveUp.forEach(id => tradeBlockPids.add(String(id)));
                    }
                }
            } catch(e) { console.warn('Could not fetch existing trade bait', e); }
        }

        let existingGiveUp = [...tradeBlockGiveUp];
        let existingExchange = '';
        console.log('[tb-submit-debug] existingGiveUp resolved to:', existingGiveUp);

const isRemoving = btn.data('removing') === true || btn.data('removing') === 'true';
        const pidStr = pid ? String(pid).trim() : '';
        if (isRemoving) {
            // Remove only what this popup is about: the player (pid), or the pick when pid is blank
            const toRemove = pidStr ? [pidStr] : newGiveUp.split(',').filter(Boolean);
            existingGiveUp = existingGiveUp.filter(id => !toRemove.includes(id));
        } else {
            newGiveUp.split(',').filter(Boolean).forEach(item => {
                if (!existingGiveUp.includes(item)) existingGiveUp.push(item);
            });
            if (pidStr && !existingGiveUp.includes(pidStr)) existingGiveUp.push(pidStr);
        }

        // Only block an empty submission when adding. Removing the last asset is allowed.
        if (existingGiveUp.length === 0 && !isRemoving) {
            alert('Please select at least one asset to add to the trade block.');
            btn.text(originalText).css({'opacity': '1', 'pointer-events': 'auto'});
            return;
        }

        let giveUpString = existingGiveUp.join(',');
