const aRes = await fetch(`${MFL_ORIGIN}/${year}/options?L=${lid}&O=43`, { credentials: 'include', cache: 'no-store' });        const aDoc = new DOMParser().parseFromString(await aRes.text(), 'text/html');
               const auctionRows = Array.from(aDoc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow'));
        const aCardsData = [];
