async function fetchWeeklyPlayerInfoMap(weekParam) {
    const map = {};
    let loggedOnce = false;
    try {
        const url = `${MFL_ORIGIN}/${year}/weekly?L=${lid}${weekParam ? `&W=${weekParam}` : ''}`;
        const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
        const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
        doc.querySelectorAll('td.two_column_layout').forEach(block => {
            let isBench = false;
            let slotIndex = 0;
            // Locate the opponent column by header text instead of a fixed index — this block's
            // own header row (not the outer page's) is what actually applies here.
            const headerRow = block.querySelector('table')?.rows[0];
            const headerThs = headerRow ? [...headerRow.querySelectorAll('th')] : [];
            const headerLabels = headerThs.map(th => th.textContent.replace(/\s+/g, ' ').trim());
            let oppThIdx = headerLabels.findIndex(t => /opp/i.test(t));
            if (oppThIdx === -1) oppThIdx = headerLabels.findIndex(t => /matchup|game/i.test(t));

            block.querySelectorAll('tr').forEach(row => {
                if (row.textContent.includes('Non-Starters') || row.textContent.includes('Bench')) {
                    isBench = true;
                }
                const pLink = row.querySelector('td.player a[class*="position_"]');
                if (!pLink) return;
                const pidMatch = pLink.getAttribute('href').match(/\d+/g);
                const pid = pidMatch ? pidMatch.pop() : null;
                if (!pid || map[pid]) return;
                const parsed = parseMFLName(pLink.textContent);
                const cells = row.querySelectorAll('td');
                const oppTdIdx = oppThIdx >= 0 ? oppThIdx - 1 : 1;
                const oppText = (oppTdIdx >= 0 && cells[oppTdIdx]) ? cells[oppTdIdx].textContent.split('(')[0].trim() : '';

                if (!loggedOnce) {
                    loggedOnce = true;
                    console.log('[weekly-debug] block header labels:', headerLabels, '| resolved opp header idx:', oppThIdx, '→ td idx:', oppTdIdx);
                    console.log('[weekly-debug] sample row cell text:', [...cells].map(td => td.textContent.replace(/\s+/g,' ').trim()));
                }

                map[pid] = {
                    name: parsed.shortName || parsed.name,
                    pos: parsed.pos,
                    realPos: parsed.realPos,
                    team: parsed.team,
                    isStarter: !isBench,
                    slotIndex: slotIndex++,
                    opp: oppText
                };
            });
        });
    } catch(e) { console.warn('Could not build weekly player info map', e); }
    return map;
}

function formatGameClock(gsr) {
    if (gsr === null || isNaN(gsr) || gsr > 3600) return null; // pregame, no clock yet
    if (gsr <= 0) return null; // final, handled elsewhere
    if (gsr === 1800) return 'Half';
    const elapsed = 3600 - gsr;
    const quarter = Math.min(4, Math.floor(elapsed / 900) + 1);
    const secsLeftInQuarter = 900 - (elapsed - (quarter - 1) * 900);
    const mins = Math.floor(secsLeftInQuarter / 60);
    const secs = secsLeftInQuarter % 60;
    const clock = `${mins}:${String(secs).padStart(2, '0')}`;
    return elapsed >= 3600 ? `OT ${clock}` : `Q${quarter} ${clock}`;
}

function deriveLiveStatus(p) {
    // The NFL schedule feed is the most reliable per-game signal, so it wins when we have it
    const sched = scheduleStatusForTeam(p.team);
    if (sched) {
        if (sched.state === 'final') return { label: 'Final', color: '#94a3b8', playing: false, done: true };
        if (sched.state === 'live') return { label: sched.label, color: '#ef4444', playing: true, done: false };
        return { label: 'Upcoming', color: '#f59e0b', playing: false, done: false };
    }
    if (p.rawStatus) {
        const s = String(p.rawStatus).toLowerCase();
        if (s.includes('final') || s.includes('post') || s.includes('bye')) return { label: 'Final', color: '#94a3b8', playing: false, done: true };
        if (s.includes('progress') || s.includes('live') || s.includes('active') || s.includes('in_game')) {
            const clock = formatGameClock(p.gsr);
            return { label: clock || 'Live', color: '#ef4444', playing: true, done: false };
        }
        if (s.includes('pre') || s.includes('not') || s.includes('sched') || s.includes('upcoming')) return { label: 'Upcoming', color: '#f59e0b', playing: false, done: false };
    }
    if (p.gsr !== null && !isNaN(p.gsr)) {
        if (p.gsr <= 0) return { label: 'Final', color: '#94a3b8', playing: false, done: true };
        if (p.gsr >= 3600) return { label: 'Upcoming', color: '#f59e0b', playing: false, done: false };
        const clock = formatGameClock(p.gsr);
        return { label: clock || 'Live', color: '#ef4444', playing: true, done: false };
    }
       // Fallback heuristic when no status/timer field is present
    if (p.score > 0) return { label: 'Final', color: '#94a3b8', playing: false, done: true };
    return { label: 'Upcoming', color: '#f59e0b', playing: false, done: false };
}

// Same three-state read (final / live / upcoming), but from the plain-text status MFL's live
// scoring feed reports (e.g. "Final", "3rd 5:23", "Sun 1:00pm") — used on the Lineup tab, which
// doesn't have gameSecondsRemaining the way the Scores tab's export payload does.
function classifyGameStatusText(text) {
    const s = (text || '').trim();
    const low = s.toLowerCase();
    if (!s) return { label: '', color: 'var(--text-dim)', playing: false, done: false };
    if (low.includes('final')) return { label: 'Final', color: '#94a3b8', playing: false, done: true };
    if (/\bq[1-4]\b/.test(low) || low.includes('ot') || low.includes('halftime') || /\d+:\d{2}/.test(s)) {
        return { label: s, color: '#ef4444', playing: true, done: false };
    }
    return { label: s, color: '#f59e0b', playing: false, done: false };
}

