        R.push(['PO', 'Make the playoffs', 'Top ' + PT + ' of ' + S.N + ' teams', b.po]); R.push(['OUT', 'Miss the playoffs', 'Finish outside the top ' + PT, b.miss]);
        R = R.slice(0, Math.max(1, parseInt(c.rn, 10) || 4));
