    const c = lldHd2Cfg(onC), d = lldHd2Def(), n = k => { const v = parseFloat(c[k]); return isFinite(v) ? v : d[k]; }, col = k => /^#[0-9a-fA-F]{3,8}$/.test(c[k]) ? c[k] : d[k];
