            <div class="slp-nm"><span class="slp-n">${data.shortName || data.name}</span><span class="slp-ps pos-text-${posL}">${pos}</span><span class="slp-tm">- ${team}<span class="slp-bye" data-team="${team}"></span></span>${inj}${stBadge}</div>
