        const usePrev = isOff && !!hdr.prev[vf], s = (usePrev ? hdr.prev[vf] : hdr.cur[vf]) || {};
        const record = s.record || (isOff ? (window._allPrevRecords?.[vf] || window._allRecords?.[vf]) : window._allRecords?.[vf]) || '';
