async function loadRecapsTab() {
    const token = ++window._recapToken;
    const st = window._recapState;
    const container = $('#league-content-container');
    const btnStyle = (on) => `padding:6px 14px; border-radius:8px; font-size:calc(10px * var(--ts,1)); font-weight:900; text-transform:uppercase; cursor:pointer; border:1px solid ${on ? 'var(--accent-blue)' : 'var(--card-border)'}; background:${on ? 'var(--accent-blue)' : 'rgba(255,255,255,0.05)'}; color:${on ? '#fff' : 'var(--text-dim)'};`;
    const viewBar = `<div style="display:flex; gap:6px; justify-content:center; margin-bottom:10px; flex-wrap:wrap;">
        ${[['week', 'Weekly'], ['preview', 'Preview'], ['month', 'Monthly'], ['awards', 'By Award'], ['team', 'By Team']].map(([v, l]) => `<button class="recap-view-btn" data-view="${v}" style="${btnStyle(st.view === v)}">${l}</button>`).join('')}</div>`;
    const loading = (txt) => container.html(`<div style="padding:10px;">${viewBar}<div style="text-align:center; padding:30px; color:var(--accent-blue); font-weight:800; font-size:calc(12px * var(--ts,1)); text-transform:uppercase; letter-spacing:1px; animation: pulse-blue 1.5s infinite;">${txt}</div></div>`);
    loading('Loading Recaps...');

    try {
        const allScores = await fetchAllWeekScores();
        const weeks = Object.keys(allScores).map(Number).sort((a, b) => a - b);
        const latest = weeks.length ? weeks[weeks.length - 1] : 0;
        if (token !== window._recapToken) return;
        if (!latest && st.view !== 'preview') { container.html(`<div style="padding:10px;">${viewBar}<div style="text-align:center; padding:24px; color:var(--text-dim); font-size:calc(11px * var(--ts,1));">No completed weeks yet.</div></div>`); return; }
        if (!st.wk || st.wk > latest) st.wk = latest;
        if (!st.fid) st.fid = (typeof myFid !== 'undefined' && myFid) ? myFid : fid;

        let inner = '';
        if (st.view === 'week') {
            const S = await getRecapSummary(st.wk, allScores, latest);
            if (token !== window._recapToken) return;
            const pickerHtml = st.pickerOpen ? `<div style="display:flex; flex-wrap:wrap; gap:6px; padding:0 2px 10px; justify-content:center;">
                ${weeks.map(w => `<div class="recap-wk-opt dashboard-pill stacked-pill" data-week="${w}" style="cursor:pointer; min-width:44px; border-bottom-color:${w === st.wk ? 'var(--accent-blue)' : 'var(--card-border)'}; opacity:${w === st.wk ? '1' : '0.6'};"><span class="pill-value" style="font-size:calc(12px * var(--ts,1)); font-weight:900; color:${w === st.wk ? 'var(--accent-blue)' : '#fff'};">W${w}</span></div>`).join('')}</div>` : '';
            const navBtn = (cls, t) => `<button class="${cls}" style="flex-shrink:0; width:22px; height:22px; border-radius:50%; background:rgba(255,255,255,0.05); border:1px solid var(--card-border); color:#fff; font-size:calc(12px * var(--ts,1)); font-weight:900; cursor:pointer;">${t}</button>`;
            inner = `<div style="display:flex; align-items:center; justify-content:center; gap:8px; margin-bottom:10px;">
                ${navBtn('recap-wk-prev', '‹')}
                <div class="recap-wk-pill dashboard-pill stacked-pill" style="cursor:pointer; border-bottom-color:var(--accent-blue);"><span class="pill-label">WEEK ${st.pickerOpen ? '▲' : '▼'}</span><span class="pill-value" style="font-size:calc(13px * var(--ts,1)); font-weight:900; color:var(--accent-blue);">${st.wk}</span></div>
                ${navBtn('recap-wk-next', '›')}
                ${st.wk === latest ? '<span style="font-size:calc(9px * var(--ts,1)); font-weight:900; color:#f59e0b; background:rgba(245,158,11,0.1); border:1px solid rgba(245,158,11,0.3); border-radius:6px; padding:3px 8px;">Latest</span>' : ''}
            </div>${pickerHtml}${S.top ? `<div style="text-align:center; margin-bottom:10px;"><button type="button" class="lld-play" data-k="recap" data-wk="${st.wk}">▶ Play Week ${st.wk} recap</button></div>` : ''}${recapWeekView(S)}`;
        } else if (st.view === 'preview') {
            const pw = Math.max(1, Math.min(18, st.pwk || (latest + 1)));
            st.pwk = pw;
            loading(`Loading Week ${pw} preview...`);
            const P = await lldBuildPreview(pw);
            if (token !== window._recapToken) return;
            const navBtn = (cls, t) => `<button class="${cls}" style="flex-shrink:0; width:22px; height:22px; border-radius:50%; background:rgba(255,255,255,0.05); border:1px solid var(--card-border); color:#fff; font-size:calc(12px * var(--ts,1)); cursor:pointer; line-height:1;">${t}</button>`;
            inner = `<div style="display:flex; align-items:center; justify-content:center; gap:8px; margin-bottom:10px;">${navBtn('pv-wk-prev', '‹')}<div class="dashboard-pill stacked-pill" style="border-bottom-color:var(--accent-blue);"><span class="pill-label">WEEK</span><span class="pill-value">${pw}</span></div>${navBtn('pv-wk-next', '›')}${pw === latest + 1 ? '<span style="font-size:calc(9px * var(--ts,1)); font-weight:900; color:#f59e0b; background:rgba(245,158,11,0.1); border:1px solid rgba(245,158,11,0.3); border-radius:6px; padding:3px 7px;">THIS WEEK</span>' : ''}</div>` + lldPreviewView(P);
        } else if (st.view === 'month') {
            const months = recapMonths(weeks);
            let cur = months.find(m => m.key === st.month) || months[months.length - 1];
            st.month = cur.key;
            const byWk = {};
            for (let i = 0; i < cur.weeks.length; i += 3) {
                loading(`Loading ${cur.label}...`);
                await Promise.all(cur.weeks.slice(i, i + 3).map(async w => { byWk[w] = await fetchRecapWeek(w, w < latest); }));
                if (token !== window._recapToken) return;
            }
            const M = computeMonthSummary(cur.weeks, byWk);
            const partial = cur.weeks.indexOf(latest) >= 0 && latest < 18 && recapMonthOf(latest + 1).key === cur.key;
            const chips = months.map(m => `<div class="recap-mo-opt dashboard-pill stacked-pill" data-mo="${m.key}" style="cursor:pointer; min-width:64px; border-bottom-color:${m.key === cur.key ? 'var(--accent-blue)' : 'var(--card-border)'}; opacity:${m.key === cur.key ? 1 : 0.7};"><span class="pill-label">${m.weeks.length > 1 ? 'W' + m.weeks[0] + '–' + m.weeks[m.weeks.length - 1] : 'W' + m.weeks[0]}</span><span class="pill-value" style="font-size:calc(12px * var(--ts,1));">${m.label.slice(0, 3).toUpperCase()}</span></div>`).join('');
            inner = `<div class="hide-scroll" style="display:flex; gap:6px; overflow-x:auto; padding:2px 2px 12px; justify-content:${months.length > 4 ? 'flex-start' : 'center'};">${chips}</div>` + recapMonthView(M, cur.label, partial);
        } else {
            const summaries = [];
            for (let w = 1; w <= latest; w += 3) {
                loading(`Loading Week ${w}${latest > 1 ? ` of ${latest}` : ''}...`);
                const batch = [];
                for (let k = w; k < w + 3 && k <= latest; k++) batch.push(getRecapSummary(k, allScores, latest));
                summaries.push(...await Promise.all(batch));
                if (token !== window._recapToken) return;
            }
            const events = recapEvents(summaries);
            window._recapEvents = events;
            if (st.view === 'awards') inner = recapAwardsView(events);
            else {
                const fids = Object.keys(leagueFranchises).filter(f => /^\d{4}$/.test(f)).sort();
                const pills = `<div class="hide-scroll" style="display:flex; gap:6px; overflow-x:auto; padding:2px 2px 12px;">${fids.map(f => `<div class="recap-team-pill" data-fid="${f}" style="flex-shrink:0; display:flex; align-items:center; gap:5px; padding:5px 9px; border-radius:8px; cursor:pointer; background:${f === st.fid ? 'rgba(59,130,246,0.15)' : 'rgba(255,255,255,0.03)'}; border:1px solid ${f === st.fid ? 'var(--accent-blue)' : 'var(--card-border)'};">${recapLogo(f, 20)}<span style="font-size:calc(9px * var(--ts,1)); font-weight:800; color:${f === st.fid ? '#fff' : 'var(--text-dim)'}; white-space:nowrap;">${leagueFranchises[f]}</span></div>`).join('')}</div>`;
                inner = pills + recapTeamView2(events, st.fid);
            }
        }
        container.html(`<div style="padding:10px;">${viewBar}${inner}</div>`);
        if (st.focusAward) {
            const gEl = document.getElementById('recap-grp-' + st.focusAward);
            st.focusAward = null;
            if (gEl) setTimeout(() => gEl.scrollIntoView({ behavior: 'smooth', block: 'start' }), 50);
        }
        reapplyAllTeamStyles();
    } catch (e) {
        console.error('Recaps error:', e);
        container.html('<div style="text-align:center; color:#ef4444; padding:20px; font-weight:800;">Failed to load recaps.</div>');
    }
}
// =================== END LEAGUE RECAPS TAB ===================
const LIVE_SCORE_POS_ORDER = ['QB', 'RB', 'WR', 'TE', 'PK', 'DL', 'LB', 'DB'];

function sortLiveScoreRoster(roster) {
    const list = [...(roster || [])];
    list.sort((a, b) => {
        // Preserve MFL's own lineup slot order (starters follow QB/RB/WR/.../FLEX/IDP sequence)
        if (a.slotIndex !== b.slotIndex) return a.slotIndex - b.slotIndex;
        const ai = LIVE_SCORE_POS_ORDER.indexOf(a.pos);
        const bi = LIVE_SCORE_POS_ORDER.indexOf(b.pos);
        if (ai !== bi) return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
        return a.name.localeCompare(b.name);
    });
        const starters = list.filter(p => p.isStarter);
    const bench = list.filter(p => !p.isStarter);
    if (window._liveScoreSort && window._liveScoreSort !== 'slot') {
        const byStatus = (a, b) => (liveStatusRank(a) - liveStatusRank(b)) || ((a.slotIndex || 0) - (b.slotIndex || 0));
        starters.sort(byStatus); bench.sort(byStatus);
    }
    return { starters, bench };
}

function buildLiveScoreSectionHeader(label) {
    return `<div class="lld-sec" style="font-size:calc(8px * var(--ts,1)); font-weight:900; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; padding:6px 4px 4px;">${label}</div>`;
}

window._liveScoreProjCache = window._liveScoreProjCache || {};async function fetchTeamProjectionsMap(fid2) {
    const wk = window._liveScoreActiveWeek;
    const cacheKey = `${fid2}_${wk}`;
    if (window._liveScoreProjCache[cacheKey]) return window._liveScoreProjCache[cacheKey];
    const map = {};
    try {
        const res = await fetch(`${MFL_ORIGIN}/${year}/lineup?L=${lid}&F=${fid2}${wk ? `&W=${wk}` : ''}`, { credentials: 'include', cache: 'no-store' });
        const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
        doc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow').forEach(row => {
            const pLink = row.querySelector('td a[class*="position_"]');
            if (!pLink) return;
            const pidMatch = pLink.getAttribute('href').match(/\d+/g);
            const pid = pidMatch ? pidMatch.pop() : null;
            if (!pid) return;
            const headerRow = row.closest('table')?.rows[0];
            const headerThs = headerRow ? [...headerRow.querySelectorAll('th')] : [];
            const projThIdx = headerThs.findIndex(th => th.textContent.replace(/\s+/g, ' ').trim() === 'Proj Pts');
            const projTdIdx = projThIdx - 1;
            const cells = row.querySelectorAll('td');
            const projVal = (projTdIdx >= 0 && cells[projTdIdx]) ? (parseFloat(cells[projTdIdx].textContent) || 0) : 0;
            map[pid] = projVal;
        });
    } catch(e) { console.warn('Could not fetch projections for', fid2, e); }
    window._liveScoreProjCache[cacheKey] = map;
    return map;
}

// League-wide player projections for a given week — NOT tied to any one franchise's roster
// page, so it isn't subject to the "can't see opponent's Proj Pts" visibility restriction
// that some leagues apply to owner logins on the /lineup page.
window._weekProjScoreCache = window._weekProjScoreCache || {};
window._weekProjDebugLogged = false;
async function fetchWeekProjectedScoresMap(wk) {
    const cacheKey = String(wk);
    if (window._weekProjScoreCache[cacheKey]) return window._weekProjScoreCache[cacheKey];
    const pKey = `lld_c_proj_${year}_${lid}_${cacheKey}`;
    { const c = lldLsGet(pKey, 6 * 3600 * 1000); if (c && Object.keys(c).length) { window._weekProjScoreCache[cacheKey] = c; return c; } }
    const map = {};
    try {
        const url = `${MFL_ORIGIN}/${year}/export?TYPE=projectedScores&L=${lid}${wk ? `&W=${wk}` : ''}&JSON=1`;
        const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
        const data = await res.json();
        if (!window._weekProjDebugLogged) {
            window._weekProjDebugLogged = true;
            console.log('[proj-debug] projectedScores URL:', url);
            console.log('[proj-debug] raw response (first 800 chars):', JSON.stringify(data).slice(0, 800));
        }
        let list = data?.projectedScores?.playerScore || [];
        if (!Array.isArray(list)) list = list ? [list] : [];
        list.forEach(p => { if (p && p.id) map[p.id] = parseFloat(p.score) || 0; });
        // MFL tells us which week the projections are for; if it isn't the week we asked for, they are not usable for that week
        const rep = parseInt(data?.projectedScores?.week, 10);
        window._projMeta = window._projMeta || {};
        window._projMeta[cacheKey] = { reported: isNaN(rep) ? null : rep, n: Object.keys(map).length };
        if (wk && !isNaN(rep) && rep !== parseInt(wk, 10)) { Object.keys(map).forEach(k => delete map[k]); window._projMeta[cacheKey].stale = true; }
    } catch(e) { console.warn('Could not fetch league-wide projected scores for week', wk, e); }
    window._weekProjScoreCache[cacheKey] = map;
    if (Object.keys(map).length && !(window._projMeta && window._projMeta[cacheKey] && window._projMeta[cacheKey].stale)) lldLsSet(pKey, map);
    return map;
}
