// NFL's own weekly schedule — confirmed real shape: <nflSchedule week><matchup kickoff
// gameSecondsRemaining><team id isHome score .../><team .../></matchup></nflSchedule>.
// gameSecondsRemaining here is PER GAME (3600=not started, 0=final, in between=live), which
// is exactly the same signal deriveLiveStatus() already knows how to read for players — so
// this can stand in for the ajax_ls feed that's been returning empty for this league.
window._nflScheduleCache = window._nflScheduleCache || {};
// NFL schedule for a week: kickoff, game clock, opponent, home/away and scores per team.
// Reads the JSON export first, then falls back to the static nfl_sched_<week>.xml file.
async function fetchNflScheduleForWeek(wk) {
    window._nflScheduleCache = window._nflScheduleCache || {};
        const cacheKey = String(wk);
    window._nflScheduleCacheAt = window._nflScheduleCacheAt || {};
    const fresh = Date.now() - (window._nflScheduleCacheAt[cacheKey] || 0) < 20000;
    const liveWeek = String(wk) === String(window._liveScoreCurrentWeek);
    if (window._nflScheduleCache[cacheKey] && (!liveWeek || fresh)) return window._nflScheduleCache[cacheKey];
    const map = {};
    const ingest = (kickoff, gsrRaw, teams) => {
        const kickoffMs = parseInt(kickoff, 10) * 1000;
        const gsr = (gsrRaw !== undefined && gsrRaw !== null && gsrRaw !== '') ? parseInt(gsrRaw, 10) : null;
        const label = kickoffMs ? new Date(kickoffMs).toLocaleString([], { weekday: 'short', hour: 'numeric', minute: '2-digit' }) : '';
        teams.forEach(t => {
            const abbr = String(t.id || '').toUpperCase();
            if (!abbr) return;
            const other = teams.find(x => x !== t);
            const home = String(t.isHome) === '1' ? true : (String(t.isHome) === '0' ? false : null);
            map[abbr] = {
                kickoffMs, label, gsr, score: parseFloat(t.score) || 0,
                opp: other ? String(other.id || '').toUpperCase() : '',
                oppScore: other ? (parseFloat(other.score) || 0) : 0,
                isHome: home
            };
        });
    };
    try {
        const res = await fetch(`https://api.myfantasyleague.com/${year}/export?TYPE=nflSchedule&W=${wk}&JSON=1`, { credentials: 'include', cache: 'no-store' });
        const data = await res.json();
        let games = data?.nflSchedule?.matchup || [];
        if (!Array.isArray(games)) games = games ? [games] : [];
        games.forEach(g => {
            let teams = g.team || [];
            if (!Array.isArray(teams)) teams = teams ? [teams] : [];
            ingest(g.kickoff, g.gameSecondsRemaining, teams);
        });
    } catch (e) { console.warn('[nfl-sched] JSON export failed for week', wk, e); }
    if (!Object.values(map).some(v => v.opp)) {
        try {
            const res = await fetch(`https://api.myfantasyleague.com/fflnetdynamic${year}/nfl_sched_${wk}.xml`, { cache: 'no-store' });
            const doc = new DOMParser().parseFromString(await res.text(), 'text/xml');
            doc.querySelectorAll('matchup').forEach(m => {
                const teams = [...m.querySelectorAll('team')].map(t => ({ id: t.getAttribute('id'), isHome: t.getAttribute('isHome'), score: t.getAttribute('score') }));
                ingest(m.getAttribute('kickoff'), m.getAttribute('gameSecondsRemaining'), teams);
            });
        } catch (e) { console.warn('[nfl-sched] XML fallback failed for week', wk, e); }
    }
    console.log('[nfl-sched] week', wk, 'teams loaded:', Object.keys(map).length);
    if (Object.keys(map).length)     window._nflScheduleCache[cacheKey] = map;
    window._nflScheduleCacheAt[cacheKey] = Date.now(); // never cache a failed/empty result
    return map;
}
async function fetchNflScheduleForWeekOld(wk) {
        const cacheKey = String(wk);
    window._nflScheduleCacheAt = window._nflScheduleCacheAt || {};
    const fresh = Date.now() - (window._nflScheduleCacheAt[cacheKey] || 0) < 20000;
    const liveWeek = String(wk) === String(window._liveScoreCurrentWeek);
    if (window._nflScheduleCache[cacheKey] && (!liveWeek || fresh)) return window._nflScheduleCache[cacheKey];
    const map = {};
    try {
        const url = `https://api.myfantasyleague.com/${year}/export?TYPE=nflSchedule&W=${wk}&JSON=1`;
        const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
        const data = await res.json();
        let games = data?.nflSchedule?.matchup || [];
        if (!Array.isArray(games)) games = games ? [games] : [];
        games.forEach(g => {
            const kickoffMs = parseInt(g.kickoff, 10) * 1000;
            const gsr = g.gameSecondsRemaining !== undefined ? parseInt(g.gameSecondsRemaining, 10) : null;
            const label = kickoffMs ? new Date(kickoffMs).toLocaleString([], { weekday: 'short', hour: 'numeric', minute: '2-digit' }) : '';
            let teams = g.team || [];
            if (!Array.isArray(teams)) teams = teams ? [teams] : [];
            teams.forEach(t => {
                const abbr = (t.id || '').toUpperCase();
                if (!abbr) return;
                map[abbr] = { kickoffMs, label, gsr, score: parseFloat(t.score) || 0 };
            });
        });
    } catch(e) { console.warn('Could not fetch nflSchedule for week', wk, e); }
    window._nflScheduleCache[cacheKey] = map;
    window._nflScheduleCacheAt[cacheKey] = Date.now();    return map;
}

window._liveScoringDetailsCache = window._liveScoringDetailsCache || {};
async function fetchLiveScoringDetails(fid2) {
    if (window._liveScoringDetailsCache[fid2]) return window._liveScoringDetailsCache[fid2];
    const details = { gameInfo: {}, stats: {} };
    try {
        const url = `${MFL_ORIGIN}/${year}/ajax_ls?L=${lid}&FRANCHISE_ID=${fid2}`;
        const res = await fetch(url, { credentials: 'include', cache: 'no-store' });
        const html = await res.text();
        const doc = new DOMParser().parseFromString(html, 'text/html');

        console.log('[ls-debug] ajax_ls URL:', url);
        console.log('[ls-debug] response length:', html.length, '| first 1000 chars:', html.slice(0, 1000));
        console.log('[ls-debug] #roster_away found:', !!doc.querySelector('#roster_away'), '| #roster_home found:', !!doc.querySelector('#roster_home'));
        console.log('[ls-debug] any element with id containing "roster":', [...doc.querySelectorAll('[id*="roster"]')].map(el => el.id));
        console.log('[ls-debug] any td with class starting "ls_":', [...doc.querySelectorAll('td[class^="ls_"]')].slice(0,5).map(el => el.className));

        ['#roster_away', '#roster_home'].forEach(sel => {
            const table = doc.querySelector(sel);
            if (!table) return;
            table.querySelectorAll('tr').forEach(row => {
                const pLink = row.querySelector('td a[href*="P="]');
                if (!pLink) return;
                const pidMatch = pLink.getAttribute('href').match(/P=(\d+)/);
                const pid = pidMatch ? pidMatch[1] : null;
                if (!pid) return;
                const gameInfoDiv = row.querySelector('td.ls_game_info div');
                const statsDiv = row.querySelector('td.ls_player_stats div');
                if (gameInfoDiv) {
                    const linkEl = gameInfoDiv.querySelector('a');
                    const scoreText = linkEl ? linkEl.textContent.trim() : '';
                    const fullText = gameInfoDiv.textContent.trim();
                    const statusText = scoreText ? fullText.replace(scoreText, '').trim() : fullText;
                    details.gameInfo[pid] = { scoreText, statusText };
                }
                if (statsDiv) {
                    const statsText = statsDiv.textContent.trim();
                    if (statsText) details.stats[pid] = statsText;
                }
            });
        });
    } catch(e) { console.warn('Could not fetch live scoring details for', fid2, e); }
    window._liveScoringDetailsCache[fid2] = details;
    return details;
}

