        const ab = t => { const w = String(t.name || '').replace(/[^A-Za-z0-9 ]/g, '').split(/\s+/).filter(Boolean); return (w.length > 1 ? w.map(x => x[0]).join('') : (w[0] || '')).slice(0, 3).toUpperCase(); };
        const sc = t => t.score.toFixed(1);
