        const line = (t, yts, proj) => `<tr><td class="g-n">${esc(t.name || '')}<small>${esc(yts || '')}</small></td><td class="g-s">${t.score.toFixed(2)}</td><td class="g-p">${px(proj)}</td></tr>`;
