// ===================== LIVE GAME STATE (clock) + PLAYING NOW + SORT =====================
const NFL_ABBR_ALIAS = { JAX: 'JAC', WSH: 'WAS', LV: 'LVR', GB: 'GBP', KC: 'KCC', NE: 'NEP', NO: 'NOS', SF: 'SFO', TB: 'TBB', LA: 'LAR' };

// Reads the NFL schedule feed for a team's game: 'pre' | 'live' | 'final', plus a label like "Q2 8:41".
function scheduleStatusForTeam(team) {
    const sched = window._liveScoreNflSchedule || {};
    const key = String(team || '').toUpperCase();
    const e = sched[key] || sched[NFL_ABBR_ALIAS[key]];
    if (!e) return null;
    const now = Date.now();
    const gsr = e.gsr;
    if (gsr !== null && gsr !== undefined && !isNaN(gsr)) {
        if (gsr <= 0) return { state: 'final', label: 'Final' };
        if (gsr < 3600) return { state: 'live', label: formatGameClock(gsr) || 'Live' };
        // Feed still says 3600 but kickoff has passed: the game has started, the clock just hasn't ticked yet
        if (e.kickoffMs && now >= e.kickoffMs && now < e.kickoffMs + 4.5 * 3600 * 1000) return { state: 'live', label: 'Live' };
        return { state: 'pre', label: e.label };
    }
    if (e.kickoffMs) {
        if (now < e.kickoffMs) return { state: 'pre', label: e.label };
        if (now < e.kickoffMs + 4.5 * 3600 * 1000) return { state: 'live', label: 'Live' };
        return { state: 'final', label: 'Final' };
    }
    return null;
}

// Scoreboard sort: 'slot' (default, lineup order), 'live' (playing first), 'ytp' (yet to play first)
window._liveScoreSort = (function () { try { return localStorage.getItem('lld_scores_sort') || 'slot'; } catch (e) { return 'slot'; } })();
function liveStatusRank(p) {
    const s = deriveLiveStatus(p);
    if (window._liveScoreSort === 'ytp') return s.playing ? 1 : (s.done ? 2 : 0);
    return s.playing ? 0 : (s.done ? 2 : 1);
}

// Strip above the starters: who is on the field right now for each side, with the game clock, plus the sort control
function buildLiveNowHtml(t1, t2, pm) {
    const mode = window._liveScoreSort || 'slot';
    const cols = (typeof scoreTeamColors === 'function') ? scoreTeamColors(t1.fid, t2.fid) : ['#3b82f6', '#3b82f6'];
    const live = t => (t.roster || []).filter(p => p.isStarter && deriveLiveStatus(p).playing).sort((a, b) => (a.slotIndex || 0) - (b.slotIndex || 0));
    const l1 = live(t1), l2 = live(t2);
    const chip = (p, color) => {
        const pos = (p.pos || '').toUpperCase(), tm = (p.team || '').toUpperCase();
        const pj = (pm && pm[p.pid] != null) ? Number(pm[p.pid]).toFixed(1) : '--';
        return `<div class="lld-ln player-modal-trigger" data-pid="${p.pid}" data-team="${tm}" data-name="${p.name}" data-pos="${pos}" style="--tc:${color};"><span class="ln-img"><img src="https://www.mflscripts.com/playerImages_80x107/mfl_${p.pid}.png" onerror="this.style.display='none'"></span><span class="ln-m"><span class="ln-pt pos-text-${pos.toLowerCase()}">${pos} ${tm}</span><span class="ln-pj">proj ${pj}</span></span><b class="ln-sc">${lldRvWrap((p.score || 0).toFixed(1), 'p' + p.pid)}</b></div>`;
    };
    const tiles = l1.map(p => chip(p, cols[0])).concat(l2.map(p => chip(p, cols[1]))).join('');
    const sortBtn = (key, label) => `<button class="live-sort-btn" data-sort="${key}" style="padding:4px 8px; border-radius:6px; font-size:calc(8px * var(--ts,1)); font-weight:900; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; border:1px solid ${mode === key ? 'var(--accent-blue)' : 'var(--card-border)'}; background:${mode === key ? 'var(--accent-blue)' : 'rgba(255,255,255,0.03)'}; color:${mode === key ? '#fff' : 'var(--text-dim)'};">${label}</button>`;
    const total = l1.length + l2.length;
    const sbCur = lldGet('lld_sb', 'theme'), sbOpen = lldGet('lld_sbopen', '') === '1';
    const sbChip = (v, l) => `<button type="button" class="lld-sb-btn lld-sbchip ${sbCur === v ? 'on' : ''}" data-v="${v}">${l}</button>`;
    const sbBar = `<div class="lld-sbbar"><button type="button" class="lld-sbopt-toggle">\u2699 Scoreboard</button><div class="lld-sbchips" ${sbOpen ? '' : 'hidden'}>${sbChip('theme', 'Match theme')}${sbChip('default', 'Default')}</div><div class="lld-sbchips" ${sbOpen ? '' : 'hidden'}>${LLD_SB_LAYOUTS.map(x => sbChip(x[0], x[1])).join('')}<button type="button" class="lld-sbtint-btn lld-sbchip ${lldGet('lld_sbtint', '') === '1' ? 'on' : ''}">Theme colors</button></div></div>`;
    return `<div id="live-now-strip" style="margin:0 0 12px;">
        ${sbBar}
        <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:6px;">
            <span style="font-size:calc(8px * var(--ts,1)); font-weight:900; text-transform:uppercase; letter-spacing:1px; color:${total ? '#ef4444' : 'var(--text-dim)'};">${total ? `<span style="display:inline-block; width:6px; height:6px; border-radius:50%; background:#ef4444; margin-right:5px; animation: pulse-blue 1.2s infinite;"></span>Playing now · ${total}` : 'Nobody playing right now'}</span>
            <div style="display:flex; gap:4px;">${sortBtn('slot', 'Lineup')}${sortBtn('live', 'Live first')}${sortBtn('ytp', 'To play')}</div>
        </div>
        ${total ? `<div class="lld-ln-grid" style="--rows:${total > 4 ? 2 : 1};">${tiles}</div>` : ''}
    </div>`;
}
