async function fetchLeagueSalaryData() {
    try {
        window.leagueSalaryData = {};
        const positions = [
            { param: 'QB', grp: 'QB' }, { param: 'RB', grp: 'RB' }, { param: 'WR', grp: 'WR' },
            { param: 'TE', grp: 'TE' }, { param: 'PK', grp: 'PK' }, { param: 'DE', grp: 'DL' },
            { param: 'DT', grp: 'DL' }, { param: 'LB', grp: 'LB' }, { param: 'CB', grp: 'DB' },
            { param: 'S',  grp: 'DB' }
        ];
        await Promise.all(positions.map(async ({ param, grp }) => {
            const res = await fetch(`${MFL_ORIGIN}/${year}/reports?L=${lid}&R=SALARIES&POS=${param}&ROOKIES=0`, { credentials: 'include', cache: 'no-store' });
            const doc = new DOMParser().parseFromString(await res.text(), 'text/html');
            doc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow').forEach(row => {
                const pLink = row.querySelector('td.player a');
                const salCell = row.querySelector('td.salary');
                if (!pLink || !salCell) return;
                const sal = parseFloat(salCell.textContent.replace(/[^0-9.]/g, '')) || 0;
                if (sal === 0) return;
                if (!window.leagueSalaryData[grp]) window.leagueSalaryData[grp] = [];
                window.leagueSalaryData[grp].push({ sal, name: pLink.textContent.trim() });
            });
        }));
        Object.keys(window.leagueSalaryData).forEach(grp => {
            window.leagueSalaryData[grp].sort((a, b) => b.sal - a.sal);
        });
    } catch (err) { console.error("Failed to fetch league salary data", err); }
}
// Makes sure team names are loaded (retrying if MFL answers with a non-JSON busy page); safe to call repeatedly
async function lldEnsureFranchiseNames() {
    if (Object.keys(leagueFranchises).length >= 2) return;
    if (window._lldNamesP) return window._lldNamesP;
    window._lldNamesP = (async () => {
        for (let a = 0; a < 4; a++) {
            if (a) await new Promise(r => setTimeout(r, 800 * a));
            try {
                const res = await fetch(`${MFL_ORIGIN}/${year}/export?TYPE=league&L=${lid}&JSON=1`, { credentials: 'include', cache: 'no-store' });
                const d = JSON.parse(await res.text());
                const list = [].concat(d?.league?.franchises?.franchise || []);
                list.forEach(f => {
                    if (!f || !f.id) return;
                    const id = String(f.id).padStart(4, '0');
                    if (!leagueFranchises[id]) leagueFranchises[id] = (f.name && String(f.name).trim()) ? f.name : ('Team ' + (parseInt(id, 10) || id));
                });
                if (list.length) return;
            } catch (e) {}
        }
    })().finally(() => { window._lldNamesP = null; });
    return window._lldNamesP;
}
