window._allPF = window._allPF || {};
window._allPF[rowFid] = row.querySelector('td.pf')?.textContent.trim() || '';
if (rowFid === myFid) window._myPF = window._allPF[rowFid];
const titleAttr = teamLink?.getAttribute('title') || '';
