    async function applyAuctionContract(pid, commentText) {
    const match = commentText.match(/\$([\d.]+)m\/yr · (\d+)yrs · (\d+)%guar/);
    if (!match) { console.warn('Could not parse contract from comment:', commentText); return; }
    const salM = parseFloat(match[1]);
    const yrs = parseInt(match[2]);
    const guar = parseInt(match[3]);
const sal = Math.round(salM * 1000000).toString();
const totalValM = (salM * yrs).toFixed(0);
    const xml = `<salaries><leagueUnit unit="LEAGUE"><player id="${pid}" salary="${sal}" contractYear="${yrs}" contractInfo="${guar}%" contractStatus="$${totalValM}M" /></leagueUnit></salaries>`;
    const params = new URLSearchParams();
    params.set('L', lid);
    params.set('DATA', xml);
    params.set('APPEND', '1');
    const res = await fetch(`${MFL_ORIGIN}/${year}/import?TYPE=salaries`, {
        method: 'POST', credentials: 'include',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: params.toString()
    });
    const txt = await res.text();

    return txt;
}

async function checkCompletedAuctions() {

    try {
        const appliedKey = `applied_contracts_${lid}_${year}`;
        const alreadyApplied = new Set(JSON.parse(localStorage.getItem(appliedKey) || '[]'));
        const res = await fetch(`${MFL_ORIGIN}/${year}/options?L=${lid}&O=102`, { credentials: 'include' });
        const txt = await res.text();
        const doc = new DOMParser().parseFromString(txt, 'text/html');
const rows = Array.from(doc.querySelectorAll('table.report tr.oddtablerow, table.report tr.eventablerow'));
rows.forEach((row, i) => {
    if (i < 4) console.log(`Row ${i}:`, row.innerHTML.substring(0, 400));
});
rows.forEach((row, i) => {
    if (i < 6) console.log(`Row ${i}:`, row.innerHTML.substring(0, 200));
});
rows.forEach((row, i) => {
    if (i < 6) console.log(`Row ${i}:`, row.innerHTML.substring(0, 300));
});
for (const row of rows) {
    const pLink = row.querySelector('a[class*="position_"]');
    if (!pLink) continue;
    const pidMatch = pLink.getAttribute('href').match(/\d+/g);
    const pid = pidMatch ? pidMatch.pop() : null;
if (!pid || alreadyApplied.has(pid)) continue;
const cells = row.querySelectorAll('td');
const commentText = cells[cells.length - 1]?.textContent.trim() || '';
const result = await applyAuctionContract(pid, commentText);
            if (result && !result.match(/<error[^>]*>/i)) {
                alreadyApplied.add(pid);
                localStorage.setItem(appliedKey, JSON.stringify([...alreadyApplied]));
            }
        }
    } catch(e) {
        console.warn('Auction contract check failed:', e);
    }
}
// --- STICKY HEADER: offset for pinned controls + condense the header on scroll ---
(function stickyHeader() {
    const header = document.querySelector('.app-header');
    if (!header) return;

    const syncOffset = () => document.documentElement.style.setProperty('--sticky-top', header.offsetHeight + 'px');
    syncOffset();
    if (window.ResizeObserver) new ResizeObserver(syncOffset).observe(header);

    let stage = 0, ticking = false; // 0 = full card, 1 = one trophy icon, 2 = name only

    function setStage(next) {
        if (document.body.classList.contains('hdr-mid')) next = 0;
        const before = header.offsetHeight;
        document.body.classList.toggle('hdr-s1', next >= 1);
        document.body.classList.toggle('hdr-s2', next >= 2);
        stage = next;
        const delta = before - header.offsetHeight; // reading offsetHeight forces the new layout
        if (delta) window.scrollBy(0, -delta);      // shrinking the header would otherwise make the rows jump
        syncOffset();
    }

    function update() {
        ticking = false;
        const y = window.scrollY, room = document.documentElement.scrollHeight - window.innerHeight;
        if (document.body.classList.contains('hdr-mid')) { if (stage !== 0) setStage(0); return; }
        let next = stage;
        if (stage === 0) {
            const full = header.offsetHeight;
            document.body.classList.add('hdr-s1'); const D = full - header.offsetHeight; document.body.classList.remove('hdr-s1'); // height the header gives back when condensed
            // condense only once the page has scrolled past that height, so growing it again never re-triggers
            if (y > D + 40 && room > D + 300) next = 1;
        } else if (y < 20) next = 0;
        if (next !== stage) {
            // Morph the header between its sizes instead of snapping (browsers without View Transitions just snap)
            if (document.body.classList.contains('lld-hdranim') && document.startViewTransition && !window._hdrVT && !(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches)) {
                window._hdrVT = true;
                try {
                    const vt = document.startViewTransition(() => setStage(next));
                    const done = () => { window._hdrVT = false; update(); };
                    vt.finished.then(done, done);
                } catch (e) { window._hdrVT = false; setStage(next); }
            } else if (!window._hdrVT) setStage(next);
        }
    }

    window.addEventListener('scroll', () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
    window.addEventListener('resize', () => { syncOffset(); update(); });
    update();

    // While condensed, tapping the slim bar jumps back to the top, where the full card and team picker are
    document.addEventListener('click', (e) => {
        if (document.body.classList.contains('hdr-s1') && e.target.closest('#active-team-switcher-btn')) {
            e.stopImmediatePropagation();
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }
    }, true);
})();
