// ===== MESSAGE BOARD (Sleeper-style, read-only) — inside the wrapper so it can use lid/year/myFid/leagueFranchises =====
const LLD_CHAT_FIDS = ['0001', '0000'];
const LLD_CHAT_ICON = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" style="height:20px; width:20px; fill:#38bdf8;"><path d="M4 3h16a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H9l-5 4v-4H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2z"/></svg>`;
function lldChatArr(x) { return x == null ? [] : (Array.isArray(x) ? x : [x]); }
async function lldChatJson(extra) {
    let last = null;
    for (let i = 0; i < 3; i++) {
        try {
            const r = await fetch(`${MFL_ORIGIN}/${year}/export?${extra}&L=${lid}&JSON=1`, { credentials: 'include', cache: 'no-store' });
            const t = await r.text();
            try { return JSON.parse(t); } catch (e) { last = 'non-JSON: ' + t.slice(0, 80).replace(/\s+/g, ' '); }
        } catch (e) { last = String(e); }
        await new Promise(r => setTimeout(r, 500 * (i + 1)));
    }
    window._lldChatDiag = last; return null;
}
function lldChatCtx() {
    return { seen: window._lldChatPrevSeen || 0, nm: f => leagueFranchises[f] || ('Team ' + (parseInt(f, 10) || f)), av: f => getFranchiseLogoUrl(f), pimg: p => `https://www.mflscripts.com/playerImages_80x107/mfl_${p}.png`, nfl: t => getNFLLogoUrl(String(t).toUpperCase()), me: myFid, now: Date.now() };
}
function lldChatOpenUrl() { return `${MFL_ORIGIN}/${year}/message_board?L=${lid}`; }
async function lldChatLoadThreads() { return (await lldChatLoadThreadsRaw()).filter(t => t.subject !== LLDTB_SUBJ && t.subject !== LLDTI_SUBJ && t.subject !== LLDSN_SUBJ); } // the trade block's data threads stay out of the chat
async function lldChatLoadThreadsRaw() {
    await lldEnsureFranchiseNames();
    const j = await lldChatJson('TYPE=messageBoard');
    const mb = j && (j.messageBoard || j.messageboard || j);
    const raw = mb ? lldChatArr(mb.thread || mb.threads || mb.topic) : [];
    return raw.map(t => ({
        id: t.id || t.threadId || t.thread || t.topic_id,
        subject: t.subject || t.title || t.topic || '',
        fid: t.franchise || t.franchise_id || t.author || t.startedBy || '',
        lastFid: t.lastPostFranchise || t.lastPoster || t.last_poster || t.franchise || t.author || '',
        ms: Number(t.lastPost || t.last_post_timestamp || t.timestamp || t.lastPostTime || 0) * 1000,
        replies: Number(t.replies || t.numReplies || t.posts || 0),
        preview: t.lastPostBody || t.preview || t.body || ''
    })).filter(t => t.id).sort((a, b) => b.ms - a.ms);
}
async function lldChatLoadPosts(id) {
    const j = await lldChatJson('TYPE=messageBoardThread&THREAD=' + encodeURIComponent(id));
    const th = j && (j.messageBoardThread || j.thread || j.messageBoard || j);
    return (th ? lldChatArr(th.post || th.posts || th.message) : []).map(p => ({
        fid: p.franchise || p.franchise_id || p.author || p.poster || '',
        ms: Number(p.timestamp || p.postTime || p.time || 0) * 1000,
        text: p.body || p.message || p.text || p.content || ''
    })).sort((a, b) => a.ms - b.ms);
}
function lldChatMount() {
    if (!document.getElementById('lld-chat')) {
        $('body').append('<div id="lld-chat"><div class="cm-box"></div></div>');
        // keep the page's own touch handlers (MFL scripts, scroll locks) away from the board so the list can scroll by touch
        const el = document.getElementById('lld-chat');
        ['touchstart', 'touchmove', 'touchend', 'wheel'].forEach(ev => el.addEventListener(ev, e => e.stopPropagation(), { passive: true }));
    }
    return $('#lld-chat .cm-box');
}
async function lldTbSeekEvents() {
    const out = [], cutoff = Date.now() - 14 * 86400000, by = {};
    const th = (await lldChatLoadThreadsRaw()).filter(t => t.subject === LLDTB_SUBJ);
    for (const t of th) {
        const posts = await lldChatLoadPosts(t.id);
        posts.forEach(p => { const o = lldTbDec(p.text); if (!o) return; const f = String(p.fid).padStart(4, '0'); (by[f] = by[f] || []).push({ ms: p.ms, p: o.p || {}, m: o.m || '' }); });
    }
    out.modes = []; window._lldTbLatest = {};
    Object.keys(by).forEach(f => {
        let prev = {}, prevM = '';
        by[f].sort((a, b) => a.ms - b.ms).forEach(st => {
            if (st.m !== prevM && (st.m === 'W' || st.m === 'R') && st.ms >= cutoff) out.modes.push({ fid: f, ms: st.ms, mode: st.m });
            prevM = st.m; window._lldTbLatest[f] = st.p;
            const fresh = [];
            Object.keys(st.p).forEach(id => { const l = lldTbParseLabel(st.p[id]), q = lldTbParseLabel(prev[id]); if (l.s === 'S' && q.s !== 'S') fresh.push({ id, asks: l.a }); });
            if (fresh.length && st.ms >= cutoff) out.push({ fid: f, ms: st.ms, fresh });
            prev = st.p;
        });
    });
    return out;
}
async function lldChatLoadActivity() {
    await lldEnsureFranchiseNames();
    const [txd, bd, pd] = await Promise.all([
        lldChatJson('TYPE=transactions&COUNT=40'),
        lldChatJson('TYPE=tradeBait&INCLUDE_DRAFT_PICKS=1'),
        lldChatJson('TYPE=pendingTrades')
    ]);
    const offers = lldChatArr(pd && pd.pendingTrades && pd.pendingTrades.pendingTrade);
    const tx = lldChatArr(txd && txd.transactions && txd.transactions.transaction);
    const baits = lldChatArr(bd && bd.tradeBaits && bd.tradeBaits.tradeBait);
    const ids = new Set();
    const pid = i => { const m = String(i).trim().match(/^(\d{3,6})(?:_.*)?$/); return m ? m[1] : null; };
    const grab = x => String(x || '').split(/[|,]/).forEach(i => { const p = pid(i); if (p) ids.add(p); });
    tx.forEach(t => { grab(t.transaction); grab(t.franchise1_gave_up); grab(t.franchise2_gave_up); }); baits.forEach(b => { grab(b.willGiveUp); }); offers.forEach(o => { grab(o.will_give_up || o.willGiveUp); grab(o.will_receive || o.willReceive); });
    let seeks = []; try { seeks = await lldTbSeekEvents(); seeks.forEach(e => e.fresh.forEach(x => grab(x.id))); } catch (e) { console.warn('seek events', e); }
    // only players labeled Seeking Trades count as on the block
    baits.forEach(b => { const f = String(b.franchise_id || b.franchise || '').padStart(4, '0'), lt = (window._lldTbLatest || {})[f]; if (lt) b.willGiveUp = String(b.willGiveUp || '').split(',').filter(id => !(lt[id.trim()] && !/^S/.test(lt[id.trim()]))).join(','); });
    const info = {}; const idl = [...ids];
    const put = p => { const n = String(p.name || '').split(',').map(x => x.trim()); info[p.id] = { id: p.id, name: n.length > 1 ? n[1] + ' ' + n[0] : n[0], pos: p.position || '', team: p.team || '' }; };
    for (let i = 0; i < idl.length; i += 60) {
        const d = await lldChatJson('TYPE=players&PLAYERS=' + idl.slice(i, i + 60).join(','));
        lldChatArr(d && d.players && d.players.player).forEach(put);
    }
    // anything the batch lookup missed: ask one at a time, then fall back to the full player list
    let miss = idl.filter(i => !info[i]);
    for (let k = 0; k < miss.length && k < 40; k++) { const d = await lldChatJson('TYPE=players&PLAYERS=' + miss[k]); lldChatArr(d && d.players && d.players.player).forEach(put); }
    miss = idl.filter(i => !info[i]);
    if (miss.length) { const d = await lldChatJson('TYPE=players'); lldChatArr(d && d.players && d.players.player).forEach(p => { if (miss.indexOf(String(p.id)) >= 0) put(p); }); }
    window._lldChatRaw = { tx: tx.slice(0, 12), missing: idl.filter(i => !info[i]) };
    const ent = id => {
        id = String(id).trim();
        if (/^DP_/.test(id)) { const q = id.split('_'); return { pick: `Round ${parseInt(q[1], 10) + 1} pick ${parseInt(q[2], 10) + 1}` }; }
        if (/^FP_/.test(id)) { const q = id.split('_'); return { pick: `${q[2]} round ${q[3]} pick` }; }
        const p = pid(id); return p ? (info[p] || { id: p, name: '', pos: '', team: '' }) : null;
    };
    const ents = x => String(x || '').split(/[,]/).map(a => a.trim()).filter(Boolean).map(ent).filter(Boolean);
    const strOf = x => ents(x).map(e => e.pick || ((e.name || ('#' + e.id)) + (e.pos ? ' (' + e.pos + ')' : ''))).join(', ');
    const LBL = { FREE_AGENT: ['Add/Drop', '#22c55e'], WAIVER: ['Waiver', '#22c55e'], BBID_WAIVER: ['Blind bid waiver', '#22c55e'], AUCTION_WON: ['Auction', '#f59e0b'], IR: ['IR move', '#94a3b8'], TAXI: ['Taxi move', '#94a3b8'] };
    const items = [];
    tx.forEach(t => {
        const ms = (parseInt(t.timestamp, 10) || 0) * 1000, ty = String(t.type || '').toUpperCase(); if (!ms) return;
        const f1 = String(t.franchise || '').padStart(4, '0');
        if (ty === 'TRADE') {
            const f2 = String(t.franchise2 || '').padStart(4, '0');
            items.push({ kind: 'tx', ms, fid: f1, fid2: f2, label: 'Trade', color: '#a855f7', cols: [{ label: 'Sent', color: '#22c55e', ents: ents(t.franchise1_gave_up) }, { label: 'Sent', color: '#22c55e', ents: ents(t.franchise2_gave_up) }] });
            return;
        }
        const parts = String(t.transaction || '').split('|'), add = ents(parts[0]), drop = ents(parts[1]);
        if (/IR|TAXI/.test(ty)) return; // roster housekeeping, not shown in the chat
        if (!add.length && !drop.length) return; // league/system housekeeping with no players
        const L = LBL[ty] || [ty.replace(/_/g, ' ').toLowerCase().replace(/^./, c => c.toUpperCase()), '#94a3b8'];
        const move = /IR|TAXI/.test(ty);
        items.push({ kind: 'tx', ms, fid: f1, label: L[0], color: L[1], cols: move ? [{ label: 'Moved', color: '#e2e8f0', ents: add.concat(drop) }] : [{ label: /WAIVER|BBID/.test(ty) ? 'Claimed' : (/AUCTION/.test(ty) ? 'Won' : 'Added'), color: '#22c55e', ents: add }, { label: 'Dropped', color: '#ef4444', ents: drop }] });
    });
    // pending trade offers (the API only exposes ones involving you; accepted trades appear above as completed trades)
    offers.forEach(o => {
        const a = String(o.offeringteam || o.offeringTeam || '').padStart(4, '0'), b = String(o.offeredto || o.offeredTo || '').padStart(4, '0');
        const ms = (parseInt(o.timestamp, 10) || 0) * 1000; if (!ms || !a.trim()) return;
        const it = { kind: 'tx', ms, fid: a, fid2: b, label: 'Trade offer · pending', color: '#a855f7', offer: true, cols: [{ label: '', color: '#22c55e', ents: ents(o.will_give_up || o.willGiveUp) }, { label: '', color: '#22c55e', ents: ents(o.will_receive || o.willReceive) }] };
        if (o.comments && String(o.comments).trim()) it.note = String(o.comments).trim();
        it.tid = String(o.trade_id || o.tradeId || o.id || ''); it.incoming = b === String(myFid).padStart(4, '0');
        it.mine = a === String(myFid).padStart(4, '0');
        const ids = x => String(x || '').split(',').map(v => v.trim()).filter(Boolean);
        it.giveIds = ids(o.will_receive || o.willReceive); it.recvIds = ids(o.will_give_up || o.willGiveUp);
        items.push(it);
    });
    seeks.forEach(e => {
        const ents2 = e.fresh.map(x => ent(x.id)).filter(Boolean); if (!ents2.length) return;
        const asks = []; e.fresh.forEach(x => x.asks.forEach(a => { const t = lldTbAskText(a); if (asks.indexOf(t) < 0) asks.push(t); }));
        const it = { kind: 'tx', ms: e.ms, fid: e.fid, label: 'Seeking trades', color: '#f59e0b', cols: [{ label: 'Shopping', color: '#f59e0b', ents: ents2 }] };
        if (asks.length) it.note = 'Looking for: ' + asks.join(', ');
        items.push(it);
    });
    (seeks.modes || []).forEach(e => { items.push({ kind: 'tx', ms: e.ms, fid: e.fid, label: 'Team outlook', color: e.mode === 'W' ? '#ef4444' : '#a78bfa', mode: e.mode, cols: [], note: e.mode === 'W' ? 'All in. Going for it this season' : 'Sellers. Rebuilding and collecting youth and picks' }); });
    // fix up the trade columns: label each side with who sent it
    items.forEach(it => { if (it.label === 'Trade' || it.offer) { if (it.offer) { it.cols[0].label = 'Offered by ' + (leagueFranchises[it.fid] || it.fid); it.cols[1].label = 'Offered by ' + (leagueFranchises[it.fid2] || it.fid2); } else { it.cols[0].label = 'Traded by ' + (leagueFranchises[it.fid] || it.fid); it.cols[1].label = 'Traded by ' + (leagueFranchises[it.fid2] || it.fid2); } } });
    // message board threads sit in the same feed
    const threads = await lldChatLoadThreads(); window._lldChatThreads = threads;
    threads.slice(0, 25).forEach(t => { if (t.ms) items.push({ kind: 'post', ms: t.ms, id: t.id, subject: t.subject, fid: t.lastFid || t.fid, preview: t.preview, replies: t.replies }); });
    try { (await lldDigestItems()).forEach(d => items.push(d)); } catch (e) { console.warn('digests', e); }
    items.sort((a, b) => a.ms - b.ms);
    const block = baits.map(b => ({ fid: String(b.franchise_id || b.franchise || '').padStart(4, '0'), give: strOf(b.willGiveUp), want: String(b.inExchangeFor || '').replace(/^\s*$/, '') })).filter(b => b.fid && b.fid !== '0000' && (b.give || b.want));
    return { items, block };
}

// Weekly Preview (Thursday morning) and Weekly Recap (Tuesday morning) cards for the message board
async function lldFirstKickoff() {
    const k = 'lld_c_wk1kick_' + year; const c = lldLsGet(k, 30 * 86400000); if (c) return c;
    let m = {}; try { m = await fetchNflScheduleForWeek(1); } catch (e) { }
    const ks = Object.keys(m || {}).map(t => m[t].kickoffMs).filter(Boolean);
    if (!ks.length) { // schedule request failed or was throttled: fall back to the Thursday after Labor Day (the NFL's usual opener) so the cards still show
        const d = new Date(Date.UTC(parseInt(year, 10), 8, 1)); while (d.getUTCDay() !== 1) d.setUTCDate(d.getUTCDate() + 1); // Labor Day
        d.setUTCDate(d.getUTCDate() + 3); return lldEtMs(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), 20, 20); // not cached, so a later good fetch wins
    }
    const v = Math.min.apply(null, ks); lldLsSet(k, v); return v;
}
// wall-clock time in US Eastern (handles daylight saving) -> UTC milliseconds
function lldEtMs(y, mo, d, h, mi) {
    const fmt = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric' });
    let t = Date.UTC(y, mo, d, h, mi);
    for (let i = 0; i < 2; i++) { const o = {}; fmt.formatToParts(new Date(t)).forEach(x => { o[x.type] = parseInt(x.value, 10); }); t += Date.UTC(y, mo, d, h, mi) - Date.UTC(o.year, o.month - 1, o.day, o.hour, o.minute); }
    return t;
}
async function lldDigestItems() {
    const k0 = await lldFirstKickoff(); if (!k0) return [];
    const q = {}; new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'numeric', day: 'numeric' }).formatToParts(new Date(k0)).forEach(x => { q[x.type] = parseInt(x.value, 10); });
    const kd = new Date(Date.UTC(q.year, q.month - 1, q.day)); // the kickoff's calendar day in Eastern time
    kd.setUTCDate(kd.getUTCDate() - ((kd.getUTCDay() - 4 + 7) % 7)); // Thursday of week 1
    const now = Date.now(), out = [];
    for (let w = 1; w <= 18; w++) {
        const th = new Date(kd); th.setUTCDate(th.getUTCDate() + 7 * (w - 1));
        const tu = new Date(th); tu.setUTCDate(tu.getUTCDate() + 5);
        const pm = lldEtMs(th.getUTCFullYear(), th.getUTCMonth(), th.getUTCDate(), 13, 30); // Thursday 1:30 PM ET
        const rm = lldEtMs(tu.getUTCFullYear(), tu.getUTCMonth(), tu.getUTCDate(), 11, 0);  // Tuesday 11:00 AM ET
        if (pm <= now) out.push({ kind: 'digest', type: 'preview', wk: w, ms: pm });
        if (rm <= now) out.push({ kind: 'digest', type: 'recap', wk: w, ms: rm });
    }
    const last = t => out.filter(x => x.type === t).slice(-2);
    return last('preview').concat(last('recap'));
}
$(document).on('click', '#lld-chat .cm-rc', function () {
    const t = $(this).data('dk'), w = parseInt($(this).data('wk'), 10);
    lldChatClose();
    lldOpenStory(t === 'recap' ? 'recap' : 'preview', w); // plays the animation; its last slide opens the full page
});

// ===== unread badge on the message board button =====
function lldChatSeenKey() { return `lld_chat_seen_${lid}_${myFid}`; }
function lldChatSeenGet() { try { const v = parseInt(localStorage.getItem(lldChatSeenKey()), 10); if (v) return v; localStorage.setItem(lldChatSeenKey(), String(Date.now() - 24 * 3600 * 1000)); return Date.now() - 24 * 3600 * 1000; } catch (e) { return Date.now() - 24 * 3600 * 1000; } }
function lldChatSeenSet() { try { localStorage.setItem(lldChatSeenKey(), String(Date.now())); } catch (e) { } }
function lldChatBadgeSet(n) {
    const b = $('#lld-chat-btn'); if (!b.length) return;
    b.toggleClass('has-new', n > 0); b.find('.cm-badge').remove();
    if (n > 0) b.append(`<span class="cm-badge">${n > 9 ? '9+' : n}</span>`);
}
function lldChatOfferSeenGet() { try { return JSON.parse(localStorage.getItem('lld_chat_offers_' + lid + '_' + myFid) || '[]'); } catch (e) { return []; } }
function lldChatOfferSeenSet(ids) { try { localStorage.setItem('lld_chat_offers_' + lid + '_' + myFid, JSON.stringify(ids.slice(-50))); } catch (e) { } }
function lldChatBadgeUpdate() { lldChatBadgeSet((window._lldChatNewOther || 0) + (window._lldChatOffers || 0)); }
// trade offers waiting on you always count until you accept or decline them (one small request, checked often)
async function lldChatCheckOffers() {
    if (!$('#lld-chat-btn').length) return;
    try {
        const pd = await lldChatJson('TYPE=pendingTrades');
        const me = String(myFid).padStart(4, '0');
        const mine = lldChatArr(pd && pd.pendingTrades && pd.pendingTrades.pendingTrade).filter(o => String(o.offeredto || o.offeredTo || '').padStart(4, '0') === me);
        window._lldChatOfferIds = mine.map(o => String(o.trade_id || o.tradeId || o.id || o.timestamp || ''));
        const seenO = lldChatOfferSeenGet();
        window._lldChatOffers = window._lldChatOfferIds.filter(i => seenO.indexOf(i) < 0).length;
        if (!$('#lld-chat').hasClass('open')) lldChatBadgeUpdate();
    } catch (e) { console.warn('offer check', e); }
}
async function lldChatCheckNew() {
    if (!$('#lld-chat-btn').length || $('#lld-chat').hasClass('open')) return;
    lldChatCheckOffers();
    try {
        const a = await lldChatLoadActivity(); window._lldChatAct = { t: Date.now(), a };
        const seen = lldChatSeenGet(), me = String(myFid).padStart(4, '0');
        window._lldChatNewOther = a.items.filter(it => it.ms > seen && !(it.offer && it.incoming) && !(it.kind === 'post' && it.fid === me) && !(it.kind === 'tx' && it.fid === me && !it.fid2 && !it.incoming)).length;
        lldChatBadgeUpdate();
        // once per page load: a new preview, recap, trade offer or completed trade since the last visit opens the chat by itself
        if (!window._lldChatAutoDone) {
            window._lldChatAutoDone = true;
            const hit = a.items.some(it => it.ms > seen && (it.kind === 'digest' || (it.kind === 'tx' && (it.offer || it.label === 'Trade'))));
            if (hit && !$('#lld-story').length && !$('#lld-chat').hasClass('open')) lldChatShowList();
        }
    } catch (e) { console.warn('chat check', e); }
}
$(document).on('visibilitychange', () => { if (!document.hidden && Date.now() - (window._lldChatAct ? window._lldChatAct.t : 0) > 120000) lldChatCheckNew(); });
// ===== chat views: 'classic' (cards) or 'feed' (a Twitter-style timeline with parody reporters) =====
const LLD_REP = { trade: { n: 'Adam Shifter', c: '#dc2626' }, block: { n: 'Matt PacAfee', c: '#d97706' }, move: { n: 'Jay Glazed', c: '#0d9488' }, recap: { n: 'Ian Rapsport', c: '#2563eb' } };
function lldChatView() { const v = lldGet('lld_chatview', ''); if (v === 'feed' || v === 'paper' || v === 'classic') return v; try { return lldEffStyle() === 'leather' ? 'paper' : 'classic'; } catch (e) { return 'classic'; } }
function lldChatViewBar() { const v = lldChatView(); return `<div class="tw-vw"><button type="button" class="cm-vw ${v === 'paper' ? 'on' : ''}" data-v="paper">Paper</button><button type="button" class="cm-vw ${v === 'feed' ? 'on' : ''}" data-v="feed">Feed</button><button type="button" class="cm-vw ${v === 'classic' ? 'on' : ''}" data-v="classic">Classic</button></div>`; }
function lldTwTime(ms) { const m = Math.round((Date.now() - ms) / 60000); if (m < 1) return 'now'; if (m < 60) return m + 'm'; const h = Math.round(m / 60); if (h < 24) return h + 'h'; const d = Math.round(h / 24); return d < 7 ? d + 'd' : new Date(ms).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }); }
function lldTwEnts(ents) { return ents.map(e => { if (e.pick) return String(e.pick); const n = String(e.name || ''), p = n.split(' '), sh = p.length > 1 ? p[0].charAt(0) + '. ' + p.slice(1).join(' ') : n; return sh + (e.pos ? ' (' + e.pos + ')' : ''); }).join(', '); }
function lldTwPost(av, name, handle, ms, body, cls, attrs) {
    return `<div class="tw ${cls || ''}" ${attrs || ''}>${av}<div class="tw-main"><div class="tw-who"><b>${lldChatEsc(name)}</b>${handle ? `<span class="tw-chk">✓</span>` : ''}<span>${handle ? '@' + lldChatEsc(handle) + ' · ' : ''}${lldTwTime(ms)}</span></div>${body}</div></div>`;
}
function lldTwRep(k) { const r = LLD_REP[k]; return { av: `<div class="tw-av" style="background:${r.c}">${r.n.split(' ').map(w => w[0]).join('')}</div>`, name: r.n, handle: r.n.replace(/ /g, '') }; }
function lldChatTweetHtml(it, ctx) {
    const chips = (cols) => `<div class="tw-emb"><div class="tw-sw">${cols.map(c => `<div class="tw-sd"><em style="color:${c.color || '#94a3b8'}">${lldChatEsc(c.label || '')}</em><div class="cm-chips">${c.ents.map(e => lldChatEntHtml(e, ctx, c.color || '#94a3b8')).join('')}</div></div>`).join('')}</div></div>`;
    if (it.kind === 'post') {
        const prev = lldChatText(it.preview || '').replace(/\s+/g, ' ').slice(0, 220);
        const av = `<img class="tw-av img" src="${lldChatEsc(ctx.av(it.fid))}" alt="">`;
        return lldTwPost(av, ctx.nm(it.fid), '', it.ms, `<div class="tw-txt"><b>${lldChatEsc(it.subject || '(no subject)')}</b>${prev ? '<br>' + lldChatEsc(prev) : ''}</div><div class="tw-act">💬 ${it.replies || 0} <span>Open thread</span></div>`, 'cm-row tw-click', `data-tid="${lldChatEsc(it.id)}"`);
    }
    if (it.kind === 'digest') {
        const r = lldTwRep('recap'), rc = it.type === 'recap';
        return lldTwPost(r.av, r.name, r.handle, it.ms, `<div class="tw-txt"><b>WEEK ${it.wk} ${rc ? 'RECAP' : 'PREVIEW'}:</b> ${rc ? 'Awards, players of the week, upsets and the standings shake-up.' : 'Projected scores, win odds, X-factors and lineup alerts for every matchup.'}</div><div class="tw-emb tw-play"><span>${rc ? 'Full recap story' : 'Full preview story'}</span><button type="button" class="cm-rc tw-pb" data-dk="${it.type}" data-wk="${it.wk}">▶ Play</button></div>`);
    }
    const A = lldChatEsc(ctx.nm(it.fid)), B = it.fid2 ? lldChatEsc(ctx.nm(it.fid2)) : '';
    const sides = it.cols.filter(c => c.ents.length);
    if (it.label === 'Trade') {
        const r = lldTwRep('trade');
        return lldTwPost(r.av, r.name, r.handle, it.ms, `<div class="tw-txt"><span class="tw-brk">BREAKING</span>Trade is done. ${A} send ${lldChatEsc(lldTwEnts(it.cols[0].ents))} to ${B} for ${lldChatEsc(lldTwEnts(it.cols[1].ents))}.</div>` + chips(sides));
    }
    if (it.offer) {
        const r = lldTwRep('trade');
        const acts = it.tid && (it.incoming || it.mine) ? `<div class="cm-acts tw-acts" data-tid="${lldChatEsc(it.tid)}" data-fid="${lldChatEsc(it.fid)}" data-give="${lldChatEsc((it.giveIds || []).join(','))}" data-recv="${lldChatEsc((it.recvIds || []).join(','))}">${it.incoming ? '<button type="button" class="cm-act ok" data-act="accept">Accept</button><button type="button" class="cm-act no" data-act="reject">Deny</button><button type="button" class="cm-act ct" data-act="counter">Counter</button>' : '<button type="button" class="cm-act no" data-act="revoke">Revoke offer</button>'}</div>` : '';
        return lldTwPost(r.av, r.name, r.handle, it.ms, `<div class="tw-txt">Trade offer on the table: ${A} would send ${lldChatEsc(lldTwEnts(it.cols[0].ents))} to ${B} for ${lldChatEsc(lldTwEnts(it.cols[1].ents))}.</div>` + chips(sides) + (it.note ? `<div class="tw-q">“${lldChatEsc(it.note)}”</div>` : '') + acts);
    }
    if (it.label === 'Team outlook') {
        const r = lldTwRep('block');
        return lldTwPost(r.av, r.name, r.handle, it.ms, `<div class="tw-txt">${it.mode === 'W' ? `Sources say ${A} are ALL IN this season and looking to win now.` : `Sources say ${A} are SELLERS and open to moving veterans.`} <span class="tw-tg">${it.mode === 'W' ? '#AllIn' : '#Sellers'}</span></div>`);
    }
    if (it.label === 'Seeking trades') {
        const r = lldTwRep('block');
        return lldTwPost(r.av, r.name, r.handle, it.ms, `<div class="tw-txt">Hearing ${A} are shopping ${lldChatEsc(lldTwEnts(it.cols[0].ents))}. ${it.note ? lldChatEsc(it.note) + '.' : 'Phone lines are open.'} <span class="tw-tg">#TradeBlock</span></div>` + chips(sides));
    }
    const r = lldTwRep('move'), parts = sides.map(c => (c.label || '').toLowerCase() + ' ' + lldTwEnts(c.ents));
    return lldTwPost(r.av, r.name, r.handle, it.ms, `<div class="tw-txt">${A}: ${lldChatEsc(parts.join(', '))}. <span class="tw-tg">#${/auction/i.test(it.label) ? 'Auction' : 'WaiverWire'}</span></div>` + chips(sides));
}
function lldPaperEnts(ents) {
    return ents.map(e => {
        if (e.pick) return lldChatEsc(String(e.pick));
        const n = String(e.name || ''), p = n.split(' '), sh = p.length > 1 ? p[0].charAt(0) + '. ' + p.slice(1).join(' ') : n, pos = String(e.pos || '').toUpperCase(), dp = (pos === 'DE' || pos === 'DT') ? 'DL' : ((pos === 'CB' || pos === 'S') ? 'DB' : pos);
        return `<a class="pp-pl player-modal-trigger" data-pid="${lldChatEsc(e.id)}" data-name="${lldChatEsc(n)}" data-pos="${lldChatEsc(dp)}" data-team="${lldChatEsc(e.team || '')}">${lldChatEsc(sh)}${pos ? ' (' + lldChatEsc(pos) + ')' : ''}</a>`;
    }).join(', ');
}
function lldChatPaperHtml(items, block, ctx) {
    const nm = f => lldChatEsc(ctx.nm(f)), cl = ms => lldChatEsc(lldChatDay(ms, ctx.now) + ', ' + lldChatClock(ms));
    const news = items.slice().sort((a, b) => b.ms - a.ms);
    const trades = news.filter(i => i.kind === 'tx' && i.label === 'Trade'), offers = news.filter(i => i.kind === 'tx' && i.offer), seeks = news.filter(i => i.kind === 'tx' && i.label === 'Seeking trades');
    const moves = news.filter(i => i.kind === 'tx' && !i.offer && i.label !== 'Trade' && i.label !== 'Seeking trades' && i.label !== 'Team outlook'), outs = news.filter(i => i.label === 'Team outlook'), posts = news.filter(i => i.kind === 'post'), digs = news.filter(i => i.kind === 'digest');
    const d = new Date(), date = d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
    let h = lldChatViewBar() + `<div class="pp"><div class="pp-mast"><div class="pp-k">Late edition</div><h1>The Dynasty Gazette</h1><div class="pp-tag"><span>${lldChatEsc(String(year))} season</span><span>${lldChatEsc(date)}</span><span>Price: one pick</span></div></div>`;
    const lead = trades[0];
    if (lead) {
        const a = lead.cols[0].ents, b = lead.cols[1].ents;
        h += `<div class="pp-lead"><div class="pp-k">Trade wire · Breaking</div><h2>${nm(lead.fid)} and ${nm(lead.fid2)} Swap Players in Trade</h2><div class="pp-by">By our trade desk · ${cl(lead.ms)}</div><div class="pp-xch"><div><b>${nm(lead.fid)} send</b>${lldPaperEnts(a)}</div><div class="m">⇄</div><div><b>${nm(lead.fid2)} send</b>${lldPaperEnts(b)}</div></div></div>`;
    } else h += `<div class="pp-lead"><div class="pp-k">Quiet on the wire</div><h2>No Trades to Report</h2><div class="pp-by">The trade desk is waiting on a deal.</div></div>`;
    if (offers.length || seeks.length || outs.length || trades.length > 1) {
        // (outlook notes are added below with the other late items)
        h += `<div class="pp-sec">Late Items</div>`;
        offers.forEach(o => { h += `<div class="pp-br"><b>Pending offer.</b> ${nm(o.fid)} propose ${lldPaperEnts(o.cols[0].ents)} to ${nm(o.fid2)} for ${lldPaperEnts(o.cols[1].ents)}. <i>${cl(o.ms)}</i>${o.tid && (o.incoming || o.mine) ? `<div class="cm-acts pp-acts" data-tid="${lldChatEsc(o.tid)}" data-fid="${lldChatEsc(o.fid)}" data-give="${lldChatEsc((o.giveIds || []).join(','))}" data-recv="${lldChatEsc((o.recvIds || []).join(','))}">${o.incoming ? '<button type="button" class="cm-act ok" data-act="accept">Accept</button><button type="button" class="cm-act no" data-act="reject">Deny</button><button type="button" class="cm-act ct" data-act="counter">Counter</button>' : '<button type="button" class="cm-act no" data-act="revoke">Revoke offer</button>'}</div>` : ''}</div>`; });
        trades.slice(1, 6).forEach(t => { h += `<div class="pp-br"><b>Trade completed.</b> ${nm(t.fid)} send ${lldPaperEnts(t.cols[0].ents)} to ${nm(t.fid2)} for ${lldPaperEnts(t.cols[1].ents)}. <i>${cl(t.ms)}</i></div>`; });
        outs.slice(0, 6).forEach(t => { h += `<div class="pp-br"><b>${nm(t.fid)} ${t.mode === 'W' ? 'go all in' : 'turn sellers'}.</b> ${lldChatEsc(t.note)}. <i>${cl(t.ms)}</i></div>`; });
        seeks.slice(0, 6).forEach(t => { h += `<div class="pp-br"><b>${nm(t.fid)} shop ${lldPaperEnts(t.cols[0].ents)}.</b> ${t.note ? lldChatEsc(t.note) + '.' : ''} <i>${cl(t.ms)}</i></div>`; });
    }
    if (digs.length) {
        h += `<div class="pp-sec">Previews and Recaps</div>`;
        digs.slice(0, 4).forEach(g => { const rc = g.type === 'recap'; h += `<div class="pp-box"><h3>Week ${g.wk} ${rc ? 'Recap' : 'Preview'}</h3><div class="pp-s">${rc ? 'Awards, players of the week, upsets and the standings shake-up' : 'Projected scores, win odds, X-factors and lineup alerts'}</div><button type="button" class="cm-rc pp-btn" data-dk="${g.type}" data-wk="${g.wk}">${rc ? 'Read the recap' : 'Read the preview'}</button></div>`; });
    }
    if (moves.length) {
        h += `<div class="pp-sec">The Wire</div>`;
        moves.slice(0, 15).forEach(m => { const parts = m.cols.filter(c => c.ents.length).map(c => (c.label || '').toLowerCase() + ' ' + lldPaperEnts(c.ents)); h += `<div class="pp-br"><b>${nm(m.fid)}</b> ${parts.join('; ')}. <i>${cl(m.ms)}</i></div>`; });
    }
    if (posts.length) {
        h += `<div class="pp-sec">Letters to the Editor</div>`;
        posts.slice(0, 10).forEach(p => { const prev = lldChatText(p.preview || '').replace(/\s+/g, ' ').slice(0, 200); h += `<div class="pp-lt cm-row" data-tid="${lldChatEsc(p.id)}">“<b>${lldChatEsc(p.subject || '(no subject)')}</b>${prev ? ' ' + lldChatEsc(prev) : ''}”<span>— ${nm(p.fid)}, ${cl(p.ms)}${p.replies ? ' · ' + p.replies + ' replies' : ''}</span></div>`; });
    }
    return h + '</div>';
}
function lldChatTweetsHtml(items, block, ctx) {
    if (!items.length) return lldChatViewBar() + '<div class="cm-empty">No recent activity.</div>';
    return lldChatViewBar() + items.slice().sort((a, b) => b.ms - a.ms).slice(0, 60).map(it => lldChatTweetHtml(it, ctx) + (window.lldSeenRow ? window.lldSeenRow(it, ctx) : '')).join('');
}
$(document).on('click', '#lld-chat .cm-vw', function () { lldSet('lld_chatview', this.dataset.v); $('.lld-cv-btn').each(function () { $(this).toggleClass('on', this.dataset.v === lldChatView()); }); lldChatShowList(); });
$(document).on('click touchend', '.player-modal-trigger', function () { window._lldPropOwner = $(this).data('owner') ? String($(this).data('owner')).padStart(4, '0') : ''; });
