            const wk = parseInt(w.week, 10);
            lldSxArr(w.matchup).forEach(m => lldSxArr(m.franchise).forEach(f => { const x = parseFloat(f.score); if (!isNaN(x) && x > 0) { (all[wk] = all[wk] || {})[String(f.id).padStart(4, '0')] = x; } }));
