            lldSxArr(st && st.leagueStandings && st.leagueStandings.franchise).forEach(f => { const w = parseInt(f.h2hw, 10), l = parseInt(f.h2hl, 10); if (!isNaN(w) && !isNaN(l)) D.rec[String(f.id).padStart(4, '0')] = { w, l, t: parseInt(f.h2ht, 10) || 0 }; });
